screenPanels.initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#history-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  let allRows = [];
  let selectedRowId = null;

  // ユーザー名マッピング（テーブル1から取得）
  const userMap = {};
  if (tables[1] && tables[1].records) {
    tables[1].records.forEach(u => {
      userMap[u.id] = u.氏名 || u.ユーザー名 || "不明";
    });
  }

  // 顧客名マッピング（テーブル5から取得）
  const customerMap = {};
  if (tables[5] && tables[5].records) {
    tables[5].records.forEach(c => {
      customerMap[c.id] = c.顧客名 || "不明";
    });
  }

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const contractId = r.契約ID || r.id || "-";
      const customerId = r.契約 ? (typeof r.契約 === 'object' ? r.契約.顧客企業ID : r.契約) : "-";
      const customerName = customerMap[customerId] || "-";
      const changeType = r.変更種別 || "-";
      const changeField = r.変更フィールド名 || "-";
      const createdAt = r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP') : "-";
      const creatorId = r.作成者ID || r.作成者 || "-";
      const creatorName = typeof creatorId === 'string' && userMap[creatorId] ? userMap[creatorId] : creatorId;
      const verifyStatus = r.請求検証ステータス || "未検証";

      // ステータスバッジの色
      let statusColor = "#9fb0d1";
      if (verifyStatus === "検証済み") statusColor = "#4ade80";
      if (verifyStatus === "不一致") statusColor = "#ef4444";

      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;">
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${contractId.substring(0, 8)}</td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${customerName}</td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${changeType}</td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${changeField}</td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${createdAt}</td>
          <td style="padding: 8px; color: var(--text); font-size: 12px;">${creatorName}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; background: ${statusColor}; color: #fff; padding: 2px 8px; border-radius: 3px; font-size: 11px; font-weight: 600;">${verifyStatus}</span>
          </td>
          <td style="padding: 8px; text-align: center;">
            <button class="detail-btn" data-id="${r.id}" style="background: transparent; color: var(--primary); border: none; font-size: 12px; cursor: pointer; text-decoration: underline;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  if (tables[2] && tables[2].records) {
    allRows = tables[2].records;
    renderRows(allRows);
  }

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const contractId = container.querySelector("#search-contract-id").value.toLowerCase();
    const customerName = container.querySelector("#search-customer-name").value.toLowerCase();
    const changeType = container.querySelector("#search-change-type").value;
    const verifyStatus = container.querySelector("#search-verify-status").value;
    const dateFrom = container.querySelector("#search-date-from").value;
    const dateTo = container.querySelector("#search-date-to").value;

    let filtered = allRows.filter(r => {
      const rContractId = (r.契約ID || r.id || "").toLowerCase();
      const rCustomerId = r.契約 ? (typeof r.契約 === 'object' ? r.契約.顧客企業ID : r.契約) : "";
      const rCustomerName = (customerMap[rCustomerId] || "").toLowerCase();
      const rChangeType = r.変更種別 || "";
      const rVerifyStatus = r.請求検証ステータス || "";
      const rCreatedAt = r.作成日時 ? new Date(r.作成日時) : null;

      if (contractId && !rContractId.includes(contractId)) return false;
      if (customerName && !rCustomerName.includes(customerName)) return false;
      if (changeType && rChangeType !== changeType) return false;
      if (verifyStatus && rVerifyStatus !== verifyStatus) return false;
      if (dateFrom && rCreatedAt && rCreatedAt < new Date(dateFrom)) return false;
      if (dateTo && rCreatedAt && rCreatedAt > new Date(dateTo)) return false;

      return true;
    });

    renderRows(filtered);
  });

  // 4. リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#search-contract-id").value = "";
    container.querySelector("#search-customer-name").value = "";
    container.querySelector("#search-change-type").value = "";
    container.querySelector("#search-verify-status").value = "";
    container.querySelector("#search-date-from").value = "";
    container.querySelector("#search-date-to").value = "";
    renderRows(allRows);
  });

  // 5. 詳細表示（イベントデリゲーション）
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const rowId = detailBtn.dataset.id;
      const row = allRows.find(r => r.id === rowId);
      if (row) {
        selectedRowId = rowId;

        // 変更前後の値をパース
        let beforeObj = {};
        let afterObj = {};
        try {
          beforeObj = row.変更前値 ? JSON.parse(row.変更前値) : {};
        } catch (e) {
          beforeObj = { raw: row.変更前値 || "-" };
        }
        try {
          afterObj = row.変更後値 ? JSON.parse(row.変更後値) : {};
        } catch (e) {
          afterObj = { raw: row.変更後値 || "-" };
        }

        const beforeText = Object.entries(beforeObj).map(([k, v]) => `${k}: ${v}`).join("\n") || "-";
        const afterText = Object.entries(afterObj).map(([k, v]) => `${k}: ${v}`).join("\n") || "-";

        container.querySelector("#detail-before").textContent = beforeText;
        container.querySelector("#detail-after").textContent = afterText;
        container.querySelector("#detail-creator").textContent = userMap[row.作成者ID] || row.作成者 || "-";
        container.querySelector("#detail-datetime").textContent = row.作成日時 ? new Date(row.作成日時).toLocaleString('ja-JP') : "-";
        container.querySelector("#detail-remark").textContent = row.備考 || "-";

        detailPanel.style.display = "block";
      }
    }
  });

  // 6. 詳細パネルを閉じる
  container.querySelector("#btn-close-detail").addEventListener("click", () => {
    detailPanel.style.display = "none";
  });

  // 7. 検証済みに変更
  container.querySelector("#btn-verify").addEventListener("click", async () => {
    if (!selectedRowId) return;
    const updated = await window.aivicApi.update(2, selectedRowId, { 請求検証ステータス: "検証済み" });
    if (updated) {
      const idx = allRows.findIndex(r => r.id === selectedRowId);
      if (idx >= 0) allRows[idx].請求検証ステータス = "検証済み";
      renderRows(allRows);
      detailPanel.style.display = "none";
    }
  });

  // 8. 不一致を報告
  container.querySelector("#btn-mismatch").addEventListener("click", async () => {
    if (!selectedRowId) return;
    const reason = prompt("不一致の理由を入力してください:");
    if (reason) {
      const updated = await window.aivicApi.update(2, selectedRowId, { 
        請求検証ステータス: "不一致",
        備考: reason
      });
      if (updated) {
        const idx = allRows.findIndex(r => r.id === selectedRowId);
        if (idx >= 0) {
          allRows[idx].請求検証ステータス = "不一致";
          allRows[idx].備考 = reason;
        }
        renderRows(allRows);
        detailPanel.style.display = "none";
      }
    }
  });

  // 9. CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    if (allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["契約ID", "顧客名", "変更種別", "変更フィールド", "変更日時", "変更者", "検証ステータス"];
    const rows = allRows.map(r => {
      const customerId = r.契約 ? (typeof r.契約 === 'object' ? r.契約.顧客企業ID : r.契約) : "-";
      const customerName = customerMap[customerId] || "-";
      const creatorName = userMap[r.作成者ID] || r.作成者 || "-";
      const createdAt = r.作成日時 ? new Date(r.作成日時).toLocaleString('ja-JP') : "-";
      return [
        r.契約ID || r.id || "-",
        customerName,
        r.変更種別 || "-",
        r.変更フィールド名 || "-",
        createdAt,
        creatorName,
        r.請求検証ステータス || "未検証"
      ];
    });

    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => {
        const str = String(cell || "");
        return str.includes(",") || str.includes('"') || str.includes("\n") 
          ? `"${str.replace(/"/g, '""')}"` 
          : str;
      }).join(",")
    ).join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `contract-history-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=請求, 1=契約, 2=請求明細, 3=顧客
  const billingTableIndex = 0;
  const contractTableIndex = 1;
  const detailTableIndex = 2;
  const customerTableIndex = 3;

  let allBillings = [];
  let selectedBilling = null;
  let selectedContract = null;

  // ステータスバッジ色
  function getStatusBadgeStyle(status) {
    const styles = {
      '未検証': 'background: rgba(255,165,0,0.2); color: #ffa500; border: 1px solid #ffa500;',
      '検証済み': 'background: rgba(76,175,80,0.2); color: #4caf50; border: 1px solid #4caf50;',
      '差異検出': 'background: rgba(244,67,54,0.2); color: #f44336; border: 1px solid #f44336;',
      '承認待ち': 'background: rgba(33,150,243,0.2); color: #2196f3; border: 1px solid #2196f3;'
    };
    return styles[status] || 'background: rgba(128,128,128,0.2); color: #808080; border: 1px solid #808080;';
  }

  // 請求一覧の再描画
  function renderBillings(rows) {
    const tbody = container.querySelector('#billing-tbody');
    tbody.innerHTML = rows.map(row => {
      const status = row.請求ステータス || '未検証';
      return `
        <tr data-id="${row.請求ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" 
            onmouseover="this.style.background='rgba(212,165,116,0.1)'" onmouseout="this.style.background='transparent'">
          <td style="padding: 0.4rem; color: var(--text); white-space: nowrap;">${row.請求ID || '-'}</td>
          <td style="padding: 0.4rem; color: var(--text); white-space: nowrap;">${row.請求年月 || '-'}</td>
          <td style="padding: 0.4rem; color: #d4a574; text-align: right; font-weight: 600; white-space: nowrap;">¥${(row.請求金額 || 0).toLocaleString()}</td>
          <td style="padding: 0.4rem; text-align: center;">
            <span style="display: inline-block; padding: 0.2rem 0.4rem; border-radius: 0.2rem; font-size: 0.75rem; font-weight: 600; ${getStatusBadgeStyle(status)}">${status}</span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 請求明細の再描画
  function renderDetails(rows) {
    const tbody = container.querySelector('#detail-tbody');
    tbody.innerHTML = rows.map(row => {
      const validationStatus = row.検証ステータス || '未検証';
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 0.4rem; color: var(--text); white-space: nowrap;">${row.明細種別 || '-'}</td>
          <td style="padding: 0.4rem; color: var(--text); text-align: right; white-space: nowrap;">${row.数量 || 0}</td>
          <td style="padding: 0.4rem; color: var(--text); text-align: right; white-space: nowrap;">¥${(row.単価 || 0).toLocaleString()}</td>
          <td style="padding: 0.4rem; color: #d4a574; text-align: right; font-weight: 600; white-space: nowrap;">¥${(row.金額 || 0).toLocaleString()}</td>
          <td style="padding: 0.4rem; text-align: center;">
            <span style="display: inline-block; padding: 0.2rem 0.4rem; border-radius: 0.2rem; font-size: 0.75rem; font-weight: 600; ${getStatusBadgeStyle(validationStatus)}">${validationStatus}</span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 契約情報の表示
  function displayContractDetail(contract, customer) {
    container.querySelector('#detail-contract-id').textContent = contract?.契約ID || '-';
    container.querySelector('#detail-customer-name').textContent = customer?.顧客名 || '-';
    container.querySelector('#detail-start-date').textContent = contract?.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#detail-end-date').textContent = contract?.契約終了日 ? new Date(contract.契約終了日).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#detail-contract-amount').textContent = contract?.契約金額 ? `¥${contract.契約金額.toLocaleString()}` : '-';
  }

  // 初期データ読み込み
  async function loadInitialData() {
    allBillings = tables[billingTableIndex]?.records || [];
    renderBillings(allBillings);
    renderDetails([]);
    displayContractDetail(null, null);
  }

  // 請求行クリック時の詳細表示
  container.addEventListener('click', async (e) => {
    const billingRow = e.target.closest('#billing-tbody tr');
    if (billingRow) {
      const billingId = billingRow.dataset.id;
      selectedBilling = allBillings.find(b => b.請求ID === billingId);

      if (selectedBilling) {
        // 契約情報を取得
        const contracts = tables[contractTableIndex]?.records || [];
        selectedContract = contracts.find(c => c.契約ID === selectedBilling.契約ID);

        // 顧客情報を取得
        const customers = tables[customerTableIndex]?.records || [];
        const customer = customers.find(cust => cust.顧客ID === selectedContract?.顧客企業ID);

        // 請求明細を取得
        const details = tables[detailTableIndex]?.records || [];
        const billingDetails = details.filter(d => d.請求ID === billingId);

        displayContractDetail(selectedContract, customer);
        renderDetails(billingDetails);
      }
    }
  });

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', () => {
    const contractId = container.querySelector('#input-contract-id').value.trim();
    const customerName = container.querySelector('#input-customer-name').value.trim();
    const periodFrom = container.querySelector('#input-period-from').value;
    const periodTo = container.querySelector('#input-period-to').value;
    const validationStatus = container.querySelector('#select-validation-status').value;

    let filtered = allBillings;

    if (contractId) {
      filtered = filtered.filter(b => b.契約ID?.includes(contractId));
    }
    if (customerName) {
      const contracts = tables[contractTableIndex]?.records || [];
      const customers = tables[customerTableIndex]?.records || [];
      const matchingContractIds = contracts
        .filter(c => {
          const cust = customers.find(cu => cu.顧客ID === c.顧客企業ID);
          return cust?.顧客名?.includes(customerName);
        })
        .map(c => c.契約ID);
      filtered = filtered.filter(b => matchingContractIds.includes(b.契約ID));
    }
    if (periodFrom) {
      filtered = filtered.filter(b => b.請求年月 >= periodFrom);
    }
    if (periodTo) {
      filtered = filtered.filter(b => b.請求年月 <= periodTo);
    }
    if (validationStatus) {
      filtered = filtered.filter(b => b.請求ステータス === validationStatus);
    }

    renderBillings(filtered);
  });

  // リセットボタン
  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#input-contract-id').value = '';
    container.querySelector('#input-customer-name').value = '';
    container.querySelector('#input-period-from').value = '';
    container.querySelector('#input-period-to').value = '';
    container.querySelector('#select-validation-status').value = '';
    renderBillings(allBillings);
  });

  // 承認ボタン
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    if (!selectedBilling) {
      alert('請求データを選択してください');
      return;
    }
    if (confirm('この請求データを承認しますか？')) {
      const updated = await window.aivicApi.update(billingTableIndex, selectedBilling.請求ID, { 請求ステータス: '検証済み' });
      if (updated) {
        allBillings = allBillings.map(b => b.請求ID === selectedBilling.請求ID ? { ...b, 請求ステータス: '検証済み' } : b);
        renderBillings(allBillings);
        alert('承認しました');
      }
    }
  });

  // 差異検出ボタン
  container.querySelector('#btn-reject').addEventListener('click', async () => {
    if (!selectedBilling) {
      alert('請求データを選択してください');
      return;
    }
    window.showScreen('scr-1781957515797');
  });

  // 詳細確認ボタン
  container.querySelector('#btn-detail').addEventListener('click', () => {
    if (!selectedBilling) {
      alert('請求データを選択してください');
      return;
    }
    window.showScreen('scr-1781957499868');
  });

  // ダッシュボードボタン
  container.querySelector('[data-testid="nav-dashboard"]').addEventListener('click', () => {
    window.showScreen('scr-1781957451550');
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス（シェルから渡される tables 配列の順序に対応）
  const contractHistoryIdx = 0;  // 契約履歴
  const billingHistoryIdx = 1;   // 請求履歴
  const contractIdx = 2;         // 契約マスタ
  const customerIdx = 3;         // 顧客マスタ

  // ========== 1. 再描画関数 ==========
  function renderContractHistory(rows) {
    const tbody = container.querySelector("#contract-history-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding: 1rem; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const verifyStatus = r.請求検証ステータス || '未検証';
      const verifyColor = verifyStatus === '検証済み' ? '#4ade80' : verifyStatus === '不一致' ? '#ff6464' : '#9fb0d1';
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 0.4rem; color: var(--text);">${formatDate(r.作成日時)}</td>
          <td style="padding: 0.4rem; color: var(--text);">${r.変更種別 || '-'}</td>
          <td style="padding: 0.4rem; color: var(--text);">${r.変更フィールド名 || '-'}</td>
          <td style="padding: 0.4rem; color: var(--text-muted); font-size: 0.75rem; max-width: 80px; overflow: hidden; text-overflow: ellipsis;">${truncate(r.変更前値, 20)}</td>
          <td style="padding: 0.4rem; color: var(--text-muted); font-size: 0.75rem; max-width: 80px; overflow: hidden; text-overflow: ellipsis;">${truncate(r.変更後値, 20)}</td>
          <td style="padding: 0.4rem; text-align: center;">
            <span style="background: rgba(${hexToRgb(verifyColor)},0.2); color: ${verifyColor}; padding: 0.2rem 0.4rem; border-radius: 0.2rem; font-size: 0.7rem; font-weight: 600;">${verifyStatus}</span>
          </td>
        </tr>
      `;
    }).join('');
  }

  function renderBillingHistory(rows) {
    const tbody = container.querySelector("#billing-history-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding: 1rem; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.請求ステータス === '支払済' ? '#4ade80' : r.請求ステータス === '延滞' ? '#ff6464' : '#9fb0d1';
      const hasDiff = r.請求金額 !== r.支払済金額;
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 0.4rem; color: var(--text);">${formatDate(r.請求日)}</td>
          <td style="padding: 0.4rem; color: var(--text);">${r.請求年月 || '-'}</td>
          <td style="padding: 0.4rem; text-align: right; color: var(--text); font-weight: 600;">¥${formatNumber(r.請求金額)}</td>
          <td style="padding: 0.4rem;">
            <span style="background: rgba(${hexToRgb(statusColor)},0.2); color: ${statusColor}; padding: 0.2rem 0.4rem; border-radius: 0.2rem; font-size: 0.7rem; font-weight: 600;">${r.請求ステータス || '-'}</span>
          </td>
          <td style="padding: 0.4rem; text-align: right; color: var(--text);">¥${formatNumber(r.支払済金額 || 0)}</td>
          <td style="padding: 0.4rem; text-align: center;">
            ${hasDiff ? '<span style="color: #ff6464; font-weight: 700;">⚠️</span>' : '<span style="color: #4ade80;">✓</span>'}
          </td>
        </tr>
      `;
    }).join('');
  }

  function renderTimeline(contractRows, billingRows) {
    const container_tl = container.querySelector("#timeline-container");

    // イベント統合：契約と請求を時系列でマージ
    const events = [];

    if (contractRows && contractRows.length > 0) {
      contractRows.forEach(r => {
        events.push({
          date: new Date(r.作成日時),
          type: 'contract',
          label: `契約変更: ${r.変更種別}`,
          detail: `${r.変更フィールド名}: ${truncate(r.変更前値, 15)} → ${truncate(r.変更後値, 15)}`,
          status: r.請求検証ステータス,
          color: r.請求検証ステータス === '検証済み' ? '#4ade80' : r.請求検証ステータス === '不一致' ? '#ff6464' : '#9fb0d1'
        });
      });
    }

    if (billingRows && billingRows.length > 0) {
      billingRows.forEach(r => {
        const hasDiff = r.請求金額 !== r.支払済金額;
        events.push({
          date: new Date(r.請求日),
          type: 'billing',
          label: `請求: ¥${formatNumber(r.請求金額)}`,
          detail: `${r.請求年月} / ${r.請求ステータス}`,
          status: hasDiff ? '差異あり' : '一致',
          color: hasDiff ? '#ff6464' : '#4ade80'
        });
      });
    }

    // 時系列ソート
    events.sort((a, b) => a.date - b.date);

    // 不整合カウント
    const mismatchCount = events.filter(e => e.status === '不一致' || e.status === '差異あり').length;
    container.querySelector("#mismatch-badge").textContent = `不整合: ${mismatchCount}件`;

    if (events.length === 0) {
      container_tl.innerHTML = '<div style="text-align: center; color: var(--text-muted); padding: 1rem;">イベントなし</div>';
      return;
    }

    container_tl.innerHTML = events.map((e, idx) => `
      <div style="display: flex; gap: 0.5rem; margin-bottom: 0.5rem; padding: 0.4rem; background: rgba(255,255,255,0.02); border-radius: 0.25rem; border-left: 3px solid ${e.color};">
        <div style="flex-shrink: 0; width: 60px; color: var(--text-muted); font-size: 0.75rem;">${formatDate(e.date)}</div>
        <div style="flex: 1;">
          <div style="color: ${e.color}; font-weight: 600; font-size: 0.8rem;">${e.label}</div>
          <div style="color: var(--text-muted); font-size: 0.75rem; margin-top: 0.2rem;">${e.detail}</div>
        </div>
        <div style="flex-shrink: 0; text-align: right;">
          <span style="background: rgba(${hexToRgb(e.color)},0.2); color: ${e.color}; padding: 0.2rem 0.4rem; border-radius: 0.2rem; font-size: 0.7rem; font-weight: 600;">${e.status}</span>
        </div>
      </div>
    `).join('');
  }

  // ========== 2. ユーティリティ関数 ==========
  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  }

  function formatNumber(num) {
    return (num || 0).toLocaleString('ja-JP');
  }

  function truncate(str, len) {
    if (!str) return '-';
    return str.length > len ? str.substring(0, len) + '...' : str;
  }

  function hexToRgb(hex) {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? `${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)}` : '159,176,209';
  }

  // ========== 3. 初期データ表示 ==========
  if (tables[contractHistoryIdx] && tables[contractHistoryIdx].records) {
    renderContractHistory(tables[contractHistoryIdx].records);
  }
  if (tables[billingHistoryIdx] && tables[billingHistoryIdx].records) {
    renderBillingHistory(tables[billingHistoryIdx].records);
  }

  // ========== 4. 検索ボタン ==========
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const contractId = container.querySelector("[data-testid='contract-id-input']").value.trim();
    const customerName = container.querySelector("[data-testid='customer-name-input']").value.trim();
    const startDate = container.querySelector("[data-testid='period-start-input']").value;
    const endDate = container.querySelector("[data-testid='period-end-input']").value;

    // 契約履歴を取得
    const contractHistoryRows = await window.aivicApi.list(contractHistoryIdx);
    let filteredContract = contractHistoryRows || [];

    if (contractId) {
      filteredContract = filteredContract.filter(r => r.契約ID && r.契約ID.includes(contractId));
    }
    if (startDate || endDate) {
      filteredContract = filteredContract.filter(r => {
        const rDate = new Date(r.作成日時);
        const start = startDate ? new Date(startDate) : new Date('1900-01-01');
        const end = endDate ? new Date(endDate) : new Date('2099-12-31');
        return rDate >= start && rDate <= end;
      });
    }

    // 請求履歴を取得
    const billingHistoryRows = await window.aivicApi.list(billingHistoryIdx);
    let filteredBilling = billingHistoryRows || [];

    if (contractId) {
      filteredBilling = filteredBilling.filter(r => r.契約ID && r.契約ID.includes(contractId));
    }
    if (startDate || endDate) {
      filteredBilling = filteredBilling.filter(r => {
        const rDate = new Date(r.請求日);
        const start = startDate ? new Date(startDate) : new Date('1900-01-01');
        const end = endDate ? new Date(endDate) : new Date('2099-12-31');
        return rDate >= start && rDate <= end;
      });
    }

    // 顧客名フィルタ（契約マスタから顧客名を取得して照合）
    if (customerName) {
      const contracts = await window.aivicApi.list(contractIdx);
      const customers = await window.aivicApi.list(customerIdx);
      const matchingContractIds = contracts
        .filter(c => {
          const cust = customers.find(cu => cu.顧客ID === c.顧客企業ID);
          return cust && cust.顧客名 && cust.顧客名.includes(customerName);
        })
        .map(c => c.契約ID);

      filteredContract = filteredContract.filter(r => matchingContractIds.includes(r.契約ID));
      filteredBilling = filteredBilling.filter(r => matchingContractIds.includes(r.契約ID));
    }

    renderContractHistory(filteredContract);
    renderBillingHistory(filteredBilling);
    renderTimeline(filteredContract, filteredBilling);
  });

  // ========== 5. リセットボタン ==========
  container.querySelector("[data-testid='reset-button']").addEventListener("click", () => {
    container.querySelector("[data-testid='contract-id-input']").value = '';
    container.querySelector("[data-testid='customer-name-input']").value = '';
    container.querySelector("[data-testid='period-start-input']").value = '';
    container.querySelector("[data-testid='period-end-input']").value = '';

    renderContractHistory(tables[contractHistoryIdx]?.records || []);
    renderBillingHistory(tables[billingHistoryIdx]?.records || []);
    container.querySelector("#timeline-container").innerHTML = '<div style="text-align: center; color: var(--text-muted); padding: 1rem;">検索実行後に表示されます</div>';
  });

  // ========== 6. ダッシュボード遷移 ==========
  container.querySelector("[data-testid='back-to-dashboard']").addEventListener("click", () => {
    window.showScreen("scr-1781957451550");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const INVOICE_TABLE = 0;
  const INVOICE_DETAIL_TABLE = 1;
  const CONTRACT_TABLE = 2;
  const CUSTOMER_TABLE = 3;
  const OPERATION_LOG_TABLE = 4;

  // 現在の請求データ
  let currentInvoice = null;
  let currentDetails = [];
  let currentContract = null;
  let currentCustomer = null;

  // 初期データ取得
  async function loadInvoiceData() {
    try {
      // 請求一覧から最初の未承認請求を取得（実装では URL パラメータで指定されることを想定）
      const invoices = tables[INVOICE_TABLE]?.records || [];
      if (invoices.length === 0) {
        console.warn("請求データがありません");
        return;
      }

      currentInvoice = invoices[0];

      // 請求明細を取得
      const details = tables[INVOICE_DETAIL_TABLE]?.records || [];
      currentDetails = details.filter(d => d.請求ID === currentInvoice.請求ID);

      // 契約情報を取得
      const contracts = tables[CONTRACT_TABLE]?.records || [];
      currentContract = contracts.find(c => c.契約ID === currentInvoice.契約ID);

      // 顧客情報を取得
      const customers = tables[CUSTOMER_TABLE]?.records || [];
      currentCustomer = customers.find(c => c.顧客ID === currentContract?.顧客企業ID);

      renderInvoiceData();
      renderInvoiceDetails();
      renderOperationLog();
    } catch (e) {
      console.error("データ読み込みエラー:", e);
    }
  }

  // 請求情報の描画
  function renderInvoiceData() {
    if (!currentInvoice || !currentContract || !currentCustomer) return;

    container.querySelector("#invoice-id").textContent = currentInvoice.請求ID?.substring(0, 8) || "—";
    container.querySelector("#invoice-month").textContent = currentInvoice.請求年月 || "—";
    container.querySelector("#invoice-date").textContent = formatDate(currentInvoice.請求日);
    container.querySelector("#payment-due").textContent = formatDate(currentInvoice.支払期限日);

    container.querySelector("#customer-name").textContent = currentCustomer.顧客名 || "—";
    container.querySelector("#contract-id").textContent = currentContract.契約ID?.substring(0, 8) || "—";
    container.querySelector("#contract-period").textContent = 
      `${formatDate(currentContract.契約開始日)} ～ ${formatDate(currentContract.契約終了日)}`;
    container.querySelector("#contract-amount").textContent = formatCurrency(currentContract.契約金額);

    // 金額計算
    const subtotal = currentDetails.reduce((sum, d) => sum + (d.金額 || 0), 0);
    const taxAmount = currentDetails.reduce((sum, d) => sum + (d.税額 || 0), 0);
    const total = subtotal + taxAmount;

    container.querySelector("#subtotal").textContent = formatCurrency(subtotal);
    container.querySelector("#tax-amount").textContent = formatCurrency(taxAmount);
    container.querySelector("#invoice-total").textContent = formatCurrency(total);

    // ステータス表示
    const statusEl = container.querySelector("#invoice-status");
    const status = currentInvoice.請求ステータス || "未承認";
    statusEl.textContent = status;
    if (status === "承認済") {
      statusEl.style.background = "rgba(100,200,100,0.15)";
      statusEl.style.color = "#64c864";
    } else if (status === "却下") {
      statusEl.style.background = "rgba(217,83,79,0.15)";
      statusEl.style.color = "#d9534f";
    } else {
      statusEl.style.background = "rgba(255,107,0,0.15)";
      statusEl.style.color = "#ff6b00";
    }
  }

  // 請求明細の描画
  function renderInvoiceDetails() {
    const tbody = container.querySelector("#invoice-details-tbody");
    tbody.innerHTML = currentDetails.map(detail => {
      const hasDiscrepancy = detail.検証ステータス === "差異検出";
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.06); ${hasDiscrepancy ? 'background: rgba(255,107,0,0.08);' : ''}">
          <td style="padding: 8px; text-align: left; color: var(--text);">${detail.明細種別 || "—"}</td>
          <td style="padding: 8px; text-align: right; color: var(--text);">${detail.数量 || 0}</td>
          <td style="padding: 8px; text-align: right; color: var(--text);">¥${(detail.単価 || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: right; color: var(--text); font-weight: 600;">¥${(detail.金額 || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 2px; font-size: 10px; font-weight: 600; ${
              hasDiscrepancy 
                ? 'background: rgba(255,107,0,0.2); color: #ff6b00;' 
                : 'background: rgba(100,200,100,0.2); color: #64c864;'
            }">
              ${hasDiscrepancy ? '⚠ 差異' : '✓ OK'}
            </span>
          </td>
        </tr>
      `;
    }).join("");

    // 差異検出アラート
    const hasDiscrepancy = currentDetails.some(d => d.検証ステータス === "差異検出");
    const alertEl = container.querySelector("#discrepancy-alert");
    if (hasDiscrepancy) {
      const discrepancies = currentDetails.filter(d => d.検証ステータス === "差異検出");
      container.querySelector("#discrepancy-msg").textContent = 
        `${discrepancies.length}件の差異が検出されています。詳細は差異検出・調整画面で確認してください。`;
      alertEl.style.display = "block";
    } else {
      alertEl.style.display = "none";
    }
  }

  // 操作ログの描画
  function renderOperationLog() {
    const logEl = container.querySelector("#operation-log");
    const logs = tables[OPERATION_LOG_TABLE]?.records || [];
    const relevantLogs = logs.filter(l => l.対象レコードID === currentInvoice?.請求ID).slice(0, 5);

    logEl.innerHTML = relevantLogs.map(log => `
      <div style="padding: 6px; background: rgba(255,255,255,0.04); border-left: 2px solid var(--primary); border-radius: 2px; color: var(--text-muted);">
        <div style="font-weight: 600; color: var(--text); margin-bottom: 2px;">${log.操作種別 || "操作"}</div>
        <div style="font-size: 10px;">${log.操作日時 ? formatDate(log.操作日時) : "—"}</div>
      </div>
    `).join("");
  }

  // 承認処理
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    showConfirmDialog(
      "請求承認確認",
      `請求ID: ${currentInvoice.請求ID?.substring(0, 8)}\n金額: ${formatCurrency(currentInvoice.請求金額)}\n\nこの請求を承認しますか？`,
      async () => {
        try {
          const updated = await window.aivicApi.update(INVOICE_TABLE, currentInvoice.請求ID, {
            請求ステータス: "承認済",
            更新日時: new Date().toISOString(),
            更新者ID: "current-user-id"
          });
          if (updated) {
            currentInvoice.請求ステータス = "承認済";
            renderInvoiceData();
            showSuccessMessage("請求を承認しました");
            setTimeout(() => window.showScreen("scr-1781957614762"), 1500);
          }
        } catch (e) {
          console.error("承認エラー:", e);
        }
      }
    );
  });

  // 却下処理
  container.querySelector("#btn-reject").addEventListener("click", () => {
    container.querySelector("#reject-reason-panel").style.display = "block";
  });

  container.querySelector("#btn-reject-cancel").addEventListener("click", () => {
    container.querySelector("#reject-reason-panel").style.display = "none";
    container.querySelector("#reject-reason").value = "";
  });

  container.querySelector("#btn-reject-confirm").addEventListener("click", async () => {
    const reason = container.querySelector("#reject-reason").value.trim();
    if (!reason) {
      alert("却下理由を入力してください");
      return;
    }

    showConfirmDialog(
      "請求却下確認",
      `請求ID: ${currentInvoice.請求ID?.substring(0, 8)}\n\n理由: ${reason}\n\nこの請求を却下しますか？`,
      async () => {
        try {
          const updated = await window.aivicApi.update(INVOICE_TABLE, currentInvoice.請求ID, {
            請求ステータス: "却下",
            摘要: reason,
            更新日時: new Date().toISOString(),
            更新者ID: "current-user-id"
          });
          if (updated) {
            currentInvoice.請求ステータス = "却下";
            renderInvoiceData();
            container.querySelector("#reject-reason-panel").style.display = "none";
            container.querySelector("#reject-reason").value = "";
            showSuccessMessage("請求を却下しました");
            setTimeout(() => window.showScreen("scr-1781957614762"), 1500);
          }
        } catch (e) {
          console.error("却下エラー:", e);
        }
      }
    );
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1781957614762");
  });

  // 契約リンククリック
  container.querySelector("#contract-id").addEventListener("click", () => {
    window.showScreen("scr-1781957631995");
  });

  // ヘルパー関数
  function formatDate(dateStr) {
    if (!dateStr) return "—";
    const d = new Date(dateStr);
    return d.toLocaleDateString("ja-JP", { year: "numeric", month: "2-digit", day: "2-digit" });
  }

  function formatCurrency(amount) {
    return `¥${(amount || 0).toLocaleString()}`;
  }

  function showConfirmDialog(title, message, onConfirm) {
    const dialog = container.querySelector("#confirm-dialog");
    container.querySelector("#confirm-title").textContent = title;
    container.querySelector("#confirm-message").textContent = message;
    dialog.style.display = "flex";

    const handleConfirm = async () => {
      dialog.style.display = "none";
      await onConfirm();
    };

    const handleCancel = () => {
      dialog.style.display = "none";
    };

    container.querySelector("#btn-confirm-ok").onclick = handleConfirm;
    container.querySelector("#btn-confirm-cancel").onclick = handleCancel;
  }

  function showSuccessMessage(text) {
    const msg = container.querySelector("#success-message");
    container.querySelector("#success-text").textContent = text;
    msg.style.display = "block";
    setTimeout(() => {
      msg.style.display = "none";
    }, 3000);
  }

  // 初期化
  loadInvoiceData();
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const contractTableIndex = tables.findIndex(t => t.tableName === '契約') ?? 0;
  const historyTableIndex = tables.findIndex(t => t.tableName === '契約履歴') ?? 1;
  const billingTableIndex = tables.findIndex(t => t.tableName === '請求') ?? 2;

  let selectedContractId = null;
  let selectedContractData = null;

  // ===== 1. 契約検索処理 =====
  container.querySelector("#btn-search-contract").addEventListener("click", async () => {
    const searchKeyword = container.querySelector("#contract-id-input").value.trim();
    if (!searchKeyword) {
      alert("契約IDまたは顧客名を入力してください");
      return;
    }

    const allContracts = await window.aivicApi.list(contractTableIndex);
    if (!allContracts) return;

    // キーワードでフィルタリング（契約IDまたは顧客名で検索）
    const filtered = allContracts.filter(c => 
      (c.契約ID && c.契約ID.includes(searchKeyword)) ||
      (c.契約名 && c.契約名.includes(searchKeyword)) ||
      (c.顧客企業ID && c.顧客企業ID.includes(searchKeyword))
    );

    if (filtered.length === 0) {
      alert("該当する契約が見つかりません");
      return;
    }

    // 最初の1件を選択
    selectedContractData = filtered[0];
    selectedContractId = selectedContractData.契約ID;

    // 現在の契約内容を表示
    const displayHtml = `
      <div style="border-left: 3px solid var(--primary); padding-left: 10px;">
        <p style="margin: 4px 0;"><strong>契約ID:</strong> ${selectedContractData.契約ID || '-'}</p>
        <p style="margin: 4px 0;"><strong>契約名:</strong> ${selectedContractData.契約名 || '-'}</p>
        <p style="margin: 4px 0;"><strong>金額:</strong> ¥${(selectedContractData.契約金額 || 0).toLocaleString()}</p>
        <p style="margin: 4px 0;"><strong>開始日:</strong> ${selectedContractData.契約開始日 ? new Date(selectedContractData.契約開始日).toLocaleDateString('ja-JP') : '-'}</p>
        <p style="margin: 4px 0;"><strong>終了日:</strong> ${selectedContractData.契約終了日 ? new Date(selectedContractData.契約終了日).toLocaleDateString('ja-JP') : '-'}</p>
        <p style="margin: 4px 0;"><strong>ステータス:</strong> ${selectedContractData.契約ステータス || '-'}</p>
      </div>
    `;
    container.querySelector("#current-contract-display").innerHTML = displayHtml;

    // 変更履歴を読み込んで表示
    const allHistory = await window.aivicApi.list(historyTableIndex);
    if (allHistory) {
      const contractHistory = allHistory.filter(h => h.契約ID === selectedContractId);
      renderChangeHistory(contractHistory);
    }

    // 比較表示をリセット
    container.querySelector("#comparison-before").innerHTML = '<p style="margin: 0; color: var(--text-muted);">-</p>';
    container.querySelector("#comparison-after").innerHTML = '<p style="margin: 0; color: var(--text-muted);">-</p>';
  });

  // ===== 2. 変更履歴タイムラインの描画 =====
  function renderChangeHistory(historyRecords) {
    if (!historyRecords || historyRecords.length === 0) {
      container.querySelector("#change-history-timeline").innerHTML = '<p style="margin: 0; color: var(--text-muted);">変更履歴がありません</p>';
      return;
    }

    const timelineHtml = historyRecords
      .sort((a, b) => new Date(b.作成日時) - new Date(a.作成日時))
      .map(h => `
        <div style="padding: 8px; margin-bottom: 8px; border-left: 2px solid var(--primary); padding-left: 10px; background: rgba(0,0,0,0.1); border-radius: 3px;">
          <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 4px;">
            ${new Date(h.作成日時).toLocaleString('ja-JP')}
          </div>
          <div style="color: var(--text); font-weight: 600; margin-bottom: 4px;">
            ${h.変更種別 || '-'}
          </div>
          <div style="color: var(--text-muted); font-size: 10px;">
            ${h.変更フィールド名 ? `フィールド: ${h.変更フィールド名}` : ''}
          </div>
          ${h.備考 ? `<div style="color: var(--text); font-size: 10px; margin-top: 4px;">${h.備考}</div>` : ''}
        </div>
      `).join('');

    container.querySelector("#change-history-timeline").innerHTML = timelineHtml;
  }

  // ===== 3. 変更前後の比較をリアルタイム更新 =====
  function updateComparison() {
    if (!selectedContractData) return;

    const changeType = container.querySelector("#change-type-select").value;
    const newPlan = container.querySelector("#new-plan-select").value;
    const newQuantity = container.querySelector("#new-quantity-input").value;
    const newPrice = container.querySelector("#new-price-input").value;
    const startDate = container.querySelector("#change-start-date-input").value;

    let beforeHtml = '<p style="margin: 0; color: var(--text-muted);">-</p>';
    let afterHtml = '<p style="margin: 0; color: var(--text-muted);">-</p>';

    if (changeType) {
      beforeHtml = `
        <p style="margin: 4px 0;"><strong>種別:</strong> ${changeType}</p>
        <p style="margin: 4px 0;"><strong>金額:</strong> ¥${(selectedContractData.契約金額 || 0).toLocaleString()}</p>
      `;

      afterHtml = `
        <p style="margin: 4px 0;"><strong>種別:</strong> ${changeType}</p>
        <p style="margin: 4px 0;"><strong>金額:</strong> ¥${(newPrice || selectedContractData.契約金額 || 0).toLocaleString()}</p>
      `;

      if (newPlan) {
        afterHtml += `<p style="margin: 4px 0;"><strong>プラン:</strong> ${newPlan}</p>`;
      }
      if (newQuantity) {
        afterHtml += `<p style="margin: 4px 0;"><strong>数量:</strong> ${newQuantity}</p>`;
      }
      if (startDate) {
        afterHtml += `<p style="margin: 4px 0;"><strong>開始日:</strong> ${new Date(startDate).toLocaleDateString('ja-JP')}</p>`;
      }
    }

    container.querySelector("#comparison-before").innerHTML = beforeHtml;
    container.querySelector("#comparison-after").innerHTML = afterHtml;
  }

  // 各入力フィールドの変更イベントリスナー
  ["change-type-select", "new-plan-select", "new-quantity-input", "new-price-input", "change-start-date-input"].forEach(id => {
    container.querySelector(`#${id}`).addEventListener("change", updateComparison);
    container.querySelector(`#${id}`).addEventListener("input", updateComparison);
  });

  // ===== 4. 変更を保存 =====
  container.querySelector("#btn-save-change").addEventListener("click", async () => {
    if (!selectedContractId) {
      alert("先に契約を検索してください");
      return;
    }

    const changeType = container.querySelector("#change-type-select").value;
    const startDate = container.querySelector("#change-start-date-input").value;
    const billingReflection = container.querySelector("#billing-reflection-select").value;

    if (!changeType || !startDate || !billingReflection) {
      alert("必須項目を入力してください（変更種別、開始日、請求反映方法）");
      return;
    }

    // 変更前値を JSON 形式で保存
    const beforeValue = JSON.stringify({
      金額: selectedContractData.契約金額,
      ステータス: selectedContractData.契約ステータス,
      開始日: selectedContractData.契約開始日
    });

    // 変更後値を JSON 形式で保存
    const newPrice = container.querySelector("#new-price-input").value;
    const afterValue = JSON.stringify({
      金額: newPrice || selectedContractData.契約金額,
      プラン: container.querySelector("#new-plan-select").value || undefined,
      数量: container.querySelector("#new-quantity-input").value || undefined,
      開始日: startDate
    });

    // 契約履歴レコードを作成
    const historyRecord = {
      契約ID: selectedContractId,
      変更種別: changeType,
      変更前値: beforeValue,
      変更後値: afterValue,
      変更フィールド名: changeType === 'price_change' ? '契約金額' : changeType === 'plan_change' ? 'プラン' : '契約内容',
      請求検証ステータス: '未検証',
      備考: container.querySelector("#change-reason-textarea").value || ''
    };

    const saved = await window.aivicApi.save(historyTableIndex, historyRecord);
    if (saved) {
      alert("変更を保存しました");
      // フォームをリセット
      container.querySelector("#change-type-select").value = '';
      container.querySelector("#new-plan-select").value = '';
      container.querySelector("#new-quantity-input").value = '';
      container.querySelector("#new-price-input").value = '';
      container.querySelector("#change-start-date-input").value = '';
      container.querySelector("#change-end-date-input").value = '';
      container.querySelector("#change-reason-textarea").value = '';
      container.querySelector("#billing-reflection-select").value = '';
      updateComparison();
    }
  });

  // ===== 5. キャンセル =====
  container.querySelector("#btn-cancel-change").addEventListener("click", () => {
    container.querySelector("#change-type-select").value = '';
    container.querySelector("#new-plan-select").value = '';
    container.querySelector("#new-quantity-input").value = '';
    container.querySelector("#new-price-input").value = '';
    container.querySelector("#change-start-date-input").value = '';
    container.querySelector("#change-end-date-input").value = '';
    container.querySelector("#change-reason-textarea").value = '';
    container.querySelector("#billing-reflection-select").value = '';
    updateComparison();
  });

  // ===== 6. 関連画面への遷移 =====
  container.querySelector("#btn-go-dashboard").addEventListener("click", () => {
    window.showScreen("scr-1781957451550");
  });

  container.querySelector("#btn-go-history-search").addEventListener("click", () => {
    window.showScreen("scr-1781957467176");
  });

  container.querySelector("#btn-go-billing-verify").addEventListener("click", () => {
    window.showScreen("scr-1781957482866");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const contractTableIndex = tables.findIndex(t => t.tableName === '契約');
  const billingTableIndex = tables.findIndex(t => t.tableName === '請求');
  const billingDetailTableIndex = tables.findIndex(t => t.tableName === '請求明細');
  const contractHistoryTableIndex = tables.findIndex(t => t.tableName === '契約履歴');
  const userTableIndex = tables.findIndex(t => t.tableName === 'ユーザー');

  // 現在のユーザー情報（実装では認証情報から取得）
  const currentUser = {
    id: 'user-001',
    name: '検証者 太郎'
  };

  // 選択状態の管理
  let selectedContractId = null;
  let selectedBillingId = null;

  // ========== 1. 詳細読み込み関数 ==========
  function loadDetails() {
    const contractSelect = container.querySelector('#contract-select');
    const billingSelect = container.querySelector('#billing-select');
    selectedContractId = contractSelect.value;
    selectedBillingId = billingSelect.value;

    if (!selectedContractId || !selectedBillingId) {
      alert('契約と請求を両方選択してください');
      return;
    }

    // 契約情報の表示
    if (contractTableIndex >= 0 && tables[contractTableIndex].records) {
      const contract = tables[contractTableIndex].records.find(r => r.id === selectedContractId);
      if (contract) {
        container.querySelector('#contract-id').textContent = contract.id || '-';
        container.querySelector('#contract-name').textContent = contract.契約名 || '-';
        container.querySelector('#contract-status').textContent = contract.契約ステータス || '-';
        container.querySelector('#contract-amount').textContent = contract.契約金額 ? `¥${contract.契約金額.toLocaleString()}` : '-';
        container.querySelector('#contract-start').textContent = contract.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '-';
        container.querySelector('#contract-end').textContent = contract.契約終了日 ? new Date(contract.契約終了日).toLocaleDateString('ja-JP') : '-';
        container.querySelector('#contract-content').textContent = contract.契約内容 || '-';
      }
    }

    // 請求情報の表示
    if (billingTableIndex >= 0 && tables[billingTableIndex].records) {
      const billing = tables[billingTableIndex].records.find(r => r.id === selectedBillingId);
      if (billing) {
        container.querySelector('#billing-id').textContent = billing.id || '-';
        container.querySelector('#billing-month').textContent = billing.請求年月 || '-';
        container.querySelector('#billing-amount').textContent = billing.請求金額 ? `¥${billing.請求金額.toLocaleString()}` : '-';
        container.querySelector('#billing-status').textContent = billing.請求ステータス || '-';
        container.querySelector('#billing-date').textContent = billing.請求日 ? new Date(billing.請求日).toLocaleDateString('ja-JP') : '-';
        container.querySelector('#billing-due').textContent = billing.支払期限日 ? new Date(billing.支払期限日).toLocaleDateString('ja-JP') : '-';
        container.querySelector('#billing-note').textContent = billing.摘要 || '-';
      }
    }

    // 契約履歴の表示
    if (contractHistoryTableIndex >= 0 && tables[contractHistoryTableIndex].records) {
      const histories = tables[contractHistoryTableIndex].records
        .filter(r => r.契約ID === selectedContractId)
        .sort((a, b) => new Date(b.作成日時) - new Date(a.作成日時))
        .slice(0, 5);

      const historyHtml = histories.length > 0
        ? histories.map(h => `
          <div style="padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.1); display: grid; grid-template-columns: 70px 1fr; gap: 8px;">
            <span style="color: var(--text-muted); font-size: 10px;">${new Date(h.作成日時).toLocaleDateString('ja-JP')}</span>
            <div>
              <div style="font-weight: 600; color: var(--primary);">${h.変更種別 || '-'}</div>
              <div style="font-size: 10px; color: var(--text-muted);">${h.変更フィールド名 || '-'}</div>
              <div style="font-size: 10px; color: var(--text); margin-top: 2px;">${h.備考 || ''}</div>
            </div>
          </div>
        `).join('')
        : '<div style="color: var(--text-muted); text-align: center; padding: 16px 0;">履歴なし</div>';

      container.querySelector('#contract-history').innerHTML = historyHtml;
