    // 差分内容の表示（請求金額と契約金額の比較）
    if (contractTableIndex >= 0 && billingTableIndex >= 0) {
      const contract = tables[contractTableIndex].records.find(r => r.id === selectedContractId);
      const billing = tables[billingTableIndex].records.find(r => r.id === selectedBillingId);

      if (contract && billing) {
        const diff = billing.請求金額 - contract.契約金額;
        if (Math.abs(diff) > 0) {
          const diffHtml = `
            <div style="padding: 8px; background: rgba(220,20,60,0.15); border-radius: 3px; margin-bottom: 8px;">
              <div style="font-weight: 600; color: #dc143c;">金額差異検出</div>
              <div style="font-size: 11px; margin-top: 4px;">
                <div>契約金額: ¥${contract.契約金額?.toLocaleString() || '-'}</div>
                <div>請求金額: ¥${billing.請求金額?.toLocaleString() || '-'}</div>
                <div style="margin-top: 4px; padding-top: 4px; border-top: 1px solid rgba(220,20,60,0.3);">
                  差異: <span style="font-weight: 600; color: #dc143c;">¥${Math.abs(diff).toLocaleString()} ${diff > 0 ? '(過請求)' : '(過少請求)'}</span>
                </div>
              </div>
            </div>
          `;
          container.querySelector('#diff-content').innerHTML = diffHtml;
        } else {
          container.querySelector('#diff-content').innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 16px 0;">差分なし</div>';
