      対象テーブル: '請求明細',
      対象レコードID: selectedBillingId,
      操作理由: `検証ステータス: ${status}, 結果: ${result}`,
      IPアドレス: '127.0.0.1',
      操作日時: new Date().toISOString()
    };

    // 実装では操作ログテーブルに保存
    // await window.aivicApi.save(operationLogTableIndex, logData);

    alert('検証結果を承認しました');
    // 画面をリセット
    container.querySelector('#verification-status').value = '';
    container.querySelector('#verification-result').value = '';
    container.querySelector('#verification-comment').value = '';
  }

  // ========== 3. 却下処理 ==========
  async function rejectVerification() {
    const comment = container.querySelector('#verification-comment').value;

    if (!comment) {
      alert('却下理由をコメント欄に記入してください');
      return;
    }

    if (!confirm('この検証結果を却下しますか？')) {
      return;
    }

    // 操作ログに記録
    const logData = {
      ユーザーID: currentUser.id,
      操作種別: '却下',
      対象テーブル: '請求明細',
      対象レコードID: selectedBillingId,
      操作理由: `却下理由: ${comment}`,
      IPアドレス: '127.0.0.1',
      操作日時: new Date().toISOString()
