    alert('検証結果を却下しました');
    // 画面をリセット
    container.querySelector('#verification-status').value = '';
    container.querySelector('#verification-result').value = '';
    container.querySelector('#verification-comment').value = '';
  }

  // ========== 4. イベントリスナー登録 ==========
  container.querySelector('#btn-load-details').addEventListener('click', loadDetails);
  container.querySelector('#btn-approve').addEventListener('click', approveVerification);
  container.querySelector('#btn-reject').addEventListener('click', rejectVerification);

  // ナビゲーション
  container.querySelector('#btn-to-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1781957451550');
  });

  container.querySelector('#btn-to-search').addEventListener('click', () => {
    window.showScreen('scr-1781957580889');
  });

  // 初期状態: メタデータを表示
  container.querySelector('#verifier-name').textContent = currentUser.name;
