function(container, apiUrl, tables) {
  const listTbody = container.querySelector("#list-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailContent = container.querySelector("#detail-content");
  const historyModal = container.querySelector("#history-modal");

  let allRows = [];
  let selectedRowId = null;

  // ステータスバッジの色付け
  function getStatusBadge(status) {
    const colors = {
      "未検証": { bg: "rgba(255, 165, 0, 0.2)", text: "#ffb84d", label: "未検証" },
      "検証済み": { bg: "rgba(76, 175, 80, 0.2)", text: "#4caf50", label: "検証済み" },
      "差異検出": { bg: "rgba(244, 67, 54, 0.2)", text: "#f44336", label: "差異検出" },
      "承認待ち": { bg: "rgba(255, 193, 7, 0.2)", text: "#ffc107", label: "承認待ち" }
    };
    const color = colors[status] || colors["未検証"];
    return `<span style="background: ${color.bg}; color: ${color.text}; padding: 3px 6px; border-radius: 3px; font-weight: 500;">${color.label}</span>`;
  }

  // 金額フォーマット
  function formatAmount(amount) {
    return (amount || 0).toLocaleString("ja-JP") + "円";
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return "-";
    const d = new Date(dateStr);
    return d.toLocaleDateString("ja-JP");
  }

  // テーブル再描画
  function renderRows(rows) {
    listTbody.innerHTML = rows.map(r => {
      const verificationStatus = r.検証ステータス || "未検証";
      const billingStatus = r.請求ステータス || "未請求";
      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 8px; color: var(--text);">${r.契約番号 || "-"}</td>
          <td style="padding: 8px; color: var(--text);">${r.顧客名 || "-"}</td>
          <td style="padding: 8px; color: var(--text);">${r.請求期間 || "-"}</td>
          <td style="padding: 8px; text-align: right; color: var(--text);">${formatAmount(r.請求金額)}</td>
          <td style="padding: 8px;">${getStatusBadge(verificationStatus)}</td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${billingStatus}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.id}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 詳細パネル表示
  function showDetail(row) {
    selectedRowId = row.id;

    // 請求詳細
    container.querySelector("#detail-billing-id").textContent = row.請求ID || "-";
    container.querySelector("#detail-billing-date").textContent = formatDate(row.請求日);
    container.querySelector("#detail-due-date").textContent = formatDate(row.支払期限日);
    container.querySelector("#detail-paid-amount").textContent = formatAmount(row.支払済金額);

    // 契約内容
    container.querySelector("#detail-contract-name").textContent = row.契約名 || "-";
    const startDate = formatDate(row.契約開始日);
    const endDate = formatDate(row.契約終了日);
    container.querySelector("#detail-contract-period").textContent = `${startDate} ～ ${endDate}`;
    container.querySelector("#detail-contract-amount").textContent = formatAmount(row.契約金額);
    container.querySelector("#detail-contract-status").textContent = row.契約ステータス || "-";

    // 請求明細（サンプル）
    const lineItems = row.請求明細 ? JSON.parse(row.請求明細) : [];
    const lineItemsHtml = lineItems.length > 0
      ? lineItems.map(item => `
          <div style="padding: 6px; border-bottom: 1px solid rgba(255,255,255,0.05); display: grid; grid-template-columns: 1fr 1fr; gap: 4px;">
            <div><span style="color: var(--text-muted);">${item.明細種別}:</span> <span style="color: var(--text);">${item.説明}</span></div>
            <div style="text-align: right; color: var(--text);">${formatAmount(item.金額)}</div>
          </div>
        `).join("")
      : `<div style="color: var(--text-muted); padding: 6px;">明細なし</div>`;
    container.querySelector("#detail-line-items").innerHTML = lineItemsHtml;

    // 検証結果
    const verificationStatus = row.検証ステータス || "未検証";
    const verificationResult = row.差異理由 || "差異なし";
    container.querySelector("#detail-verification-result").innerHTML = `
      <div style="margin-bottom: 6px;">${getStatusBadge(verificationStatus)}</div>
      <div style="color: var(--text-muted); font-size: 11px;">${verificationResult}</div>
    `;

    detailContent.style.display = "flex";
    container.querySelector("#detail-panel > div:first-child").style.display = "none";
  }

  // 詳細パネル非表示
  function hideDetail() {
    detailContent.style.display = "none";
    container.querySelector("#detail-panel > div:first-child").style.display = "block";
    selectedRowId = null;
  }

  // 契約履歴表示
  function showHistory(contractId) {
    const historyTimeline = container.querySelector("#history-timeline");

    // サンプル履歴データ
    const historyItems = [
      { date: "2024-01-15", type: "新規作成", field: "契約ID", before: "-", after: contractId, user: "営業太郎" },
      { date: "2024-01-20", type: "更新", field: "契約金額", before: "1,000,000", after: "1,200,000", user: "営業花子" },
      { date: "2024-02-01", type: "更新", field: "契約ステータス", before: "提案中", after: "契約済", user: "管理者" }
    ];

    historyTimeline.innerHTML = historyItems.map(item => `
      <div style="padding: 12px; border-left: 3px solid var(--primary); margin-bottom: 8px; background: rgba(255,255,255,0.02); border-radius: 4px;">
        <div style="font-weight: 600; color: var(--text); margin-bottom: 4px;">${item.type}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">${item.date} by ${item.user}</div>
        <div style="font-size: 11px; color: var(--text);">
          <span style="color: var(--text-muted);">${item.field}:</span>
          <span style="text-decoration: line-through; color: #f44336;">${item.before}</span>
          <span style="margin: 0 4px;">→</span>
          <span style="color: #4caf50; font-weight: 500;">${item.after}</span>
        </div>
      </div>
    `).join("");

    historyModal.style.display = "flex";
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allRows = rows || [];
    renderRows(allRows);
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const contractId = container.querySelector("#filter-contract-id").value.toLowerCase();
    const customerName = container.querySelector("#filter-customer-name").value.toLowerCase();
    const billingMonth = container.querySelector("#filter-billing-month").value;
    const verificationStatus = container.querySelector("#filter-verification-status").value;
    const amountMin = parseInt(container.querySelector("#filter-amount-min").value) || 0;
    const amountMax = parseInt(container.querySelector("#filter-amount-max").value) || Infinity;

    const filtered = allRows.filter(r => {
      const matchContract = !contractId || (r.契約番号 || "").toLowerCase().includes(contractId);
      const matchCustomer = !customerName || (r.顧客名 || "").toLowerCase().includes(customerName);
      const matchMonth = !billingMonth || (r.請求期間 || "").startsWith(billingMonth);
      const matchStatus = !verificationStatus || r.検証ステータス === verificationStatus;
      const matchAmount = (r.請求金額 || 0) >= amountMin && (r.請求金額 || 0) <= amountMax;
      return matchContract && matchCustomer && matchMonth && matchStatus && matchAmount;
    });

    renderRows(filtered);
  });

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#filter-contract-id").value = "";
    container.querySelector("#filter-customer-name").value = "";
    container.querySelector("#filter-billing-month").value = "";
    container.querySelector("#filter-verification-status").value = "";
    container.querySelector("#filter-amount-min").value = "";
    container.querySelector("#filter-amount-max").value = "";
    renderRows(allRows);
  });

  // CSV出力
  container.querySelector("#btn-export").addEventListener("click", () => {
    const rows = listTbody.querySelectorAll("tr");
    const headers = ["契約番号", "顧客名", "請求期間", "請求金額", "検証ステータス", "請求ステータス"];
    const csv = [headers.join(",")];

    rows.forEach(row => {
      const cells = row.querySelectorAll("td");
      const data = [
        cells[0].textContent,
        cells[1].textContent,
        cells[2].textContent,
        cells[3].textContent.replace("円", ""),
        cells[4].textContent.trim(),
        cells[5].textContent
      ];
      csv.push(data.map(d => `"${d}"`).join(","));
    });

    const bom = "\uFEFF";
    const blob = new Blob([bom + csv.join("\n")], { type: "text/csv; charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "billing-verification-" + new Date().toISOString().split("T")[0] + ".csv";
    link.click();
  });

  // 詳細ボタン
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const rowId = detailBtn.dataset.id;
      const row = allRows.find(r => r.id === rowId);
      if (row) showDetail(row);
    }

    const verifyBtn = e.target.closest("#btn-detail-verify");
    if (verifyBtn && selectedRowId) {
      alert("検証処理を実行します（実装予定）");
      // 実装: 検証ロジック
    }

    const closeBtn = e.target.closest("#btn-detail-close");
    if (closeBtn) hideDetail();

    const historyCloseBtn = e.target.closest("#btn-history-close");
    if (historyCloseBtn) historyModal.style.display = "none";
  });

  // 行クリックで詳細表示
  container.addEventListener("click", e => {
    const tr = e.target.closest("tr");
    if (tr && !e.target.closest("button")) {
      const rowId = tr.dataset.id;
      const row = allRows.find(r => r.id === rowId);
      if (row) showDetail(row);
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=契約, 1=顧客, 2=契約履歴, 3=請求
  const contractTable = tables[0];
  const customerTable = tables[1];
  const historyTable = tables[2];
  const billingTable = tables[3];

  let allContracts = contractTable?.records || [];
  let allCustomers = customerTable?.records || [];
  let selectedContractId = null;

  // ===== 1. 契約一覧の再描画 =====
  function renderContractList(contracts) {
    const tbody = container.querySelector("#contract-tbody");
    tbody.innerHTML = contracts.map(contract => {
      const startDate = contract.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '—';
      const status = contract.契約ステータス || '—';
      return `
        <tr 
          data-id="${contract.契約ID}" 
          style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s;"
          onmouseover="this.style.background='rgba(255,165,0,0.08)'"
          onmouseout="this.style.background='transparent'"
        >
          <td style="padding: 0.5rem; color: var(--text);">${contract.契約ID?.substring(0, 8) || '—'}</td>
          <td style="padding: 0.5rem; color: var(--text);">${startDate}</td>
          <td style="padding: 0.5rem; color: #ffa500; font-weight: 500;">${status}</td>
        </tr>
      `;
    }).join("");
  }

  // ===== 2. 契約詳細の表示 =====
  function showContractDetail(contractId) {
    const contract = allContracts.find(c => c.契約ID === contractId);
    if (!contract) {
      container.querySelector("#contract-detail").innerHTML = '<div style="color: var(--text-muted); font-size: 12px;">契約を選択してください</div>';
      return;
    }

    selectedContractId = contractId;
    const customer = allCustomers.find(c => c.顧客ID === contract.顧客企業ID);

    // 契約詳細を更新
    container.querySelector("#detail-contract-id").textContent = contract.契約ID?.substring(0, 12) || '—';
    container.querySelector("#detail-customer-name").textContent = customer?.顧客名 || '—';
    container.querySelector("#detail-contract-name").textContent = contract.契約名 || '—';
    container.querySelector("#detail-status").textContent = contract.契約ステータス || '—';
    container.querySelector("#detail-start-date").textContent = contract.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '—';
    container.querySelector("#detail-end-date").textContent = contract.契約終了日 ? new Date(contract.契約終了日).toLocaleDateString('ja-JP') : '—';
    container.querySelector("#detail-amount").textContent = contract.契約金額 ? `¥${contract.契約金額.toLocaleString()}` : '—';
    container.querySelector("#detail-content").textContent = contract.契約内容 || '契約内容なし';

    // 割引基準情報（契約内容から推定）
    const discountInfo = extractDiscountInfo(contract);
    container.querySelector("#discount-type").textContent = discountInfo.type || '標準割引';
    container.querySelector("#discount-value").textContent = discountInfo.value || '—';
    container.querySelector("#discount-condition").textContent = discountInfo.condition || '条件なし';
    container.querySelector("#discount-start").textContent = discountInfo.startDate || '—';
    container.querySelector("#discount-end").textContent = discountInfo.endDate || '—';
  }

  // ===== 3. 割引基準情報の抽出（契約内容から） =====
  function extractDiscountInfo(contract) {
    // 実装例：契約内容に割引情報が含まれていると仮定
    const content = contract.契約内容 || '';
    let type = '標準割引';
    let value = '—';
    let condition = '条件なし';
    let startDate = contract.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '—';
    let endDate = contract.契約終了日 ? new Date(contract.契約終了日).toLocaleDateString('ja-JP') : '—';

    if (content.includes('10%')) {
      type = '数量割引';
      value = '10%';
      condition = '月間購入額100万円以上';
    } else if (content.includes('5%')) {
      type = '継続割引';
      value = '5%';
      condition = '契約期間中継続';
    } else if (content.includes('15%')) {
      type = '特別割引';
      value = '15%';
      condition = '特定商品対象';
    }

    return { type, value, condition, startDate, endDate };
  }

  // ===== 4. 初期データの描画 =====
  renderContractList(allContracts);
  if (allContracts.length > 0) {
    showContractDetail(allContracts[0].契約ID);
  }

  // ===== 5. 検索ボタンのイベント =====
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const customerId = container.querySelector("#input-customer-id").value.trim();
    const customerName = container.querySelector("#input-customer-name").value.trim();

    // API から最新データを取得
    const contracts = await window.aivicApi.list(0);
    if (!contracts) {
      renderContractList(allContracts);
      return;
    }

    allContracts = contracts;

    // フィルタリング
    let filtered = allContracts;
    if (customerId) {
      filtered = filtered.filter(c => c.顧客企業ID?.includes(customerId));
    }
    if (customerName) {
      const matchingCustomers = allCustomers.filter(c => c.顧客名?.includes(customerName));
      const matchingIds = matchingCustomers.map(c => c.顧客ID);
      filtered = filtered.filter(c => matchingIds.includes(c.顧客企業ID));
    }

    renderContractList(filtered);
    if (filtered.length > 0) {
      showContractDetail(filtered[0].契約ID);
    }
  });

  // ===== 6. 契約行クリックで詳細表示 =====
  container.querySelector("#contract-tbody").addEventListener("click", (e) => {
    const row = e.target.closest("tr");
    if (row) {
      const contractId = row.dataset.id;
      showContractDetail(contractId);
    }
  });

  // ===== 7. 履歴表示ボタン =====
  container.querySelector("#btn-view-history").addEventListener("click", () => {
    if (!selectedContractId) {
      alert("契約を選択してください");
      return;
    }
    window.showScreen("scr-1781957580889"); // 契約履歴・請求データ検索画面
  });

  // ===== 8. 請求情報ボタン =====
  container.querySelector("#btn-view-billing").addEventListener("click", () => {
    if (!selectedContractId) {
      alert("契約を選択してください");
      return;
    }
    window.showScreen("scr-1781957482866"); // 請求データ検証画面
  });

  // ===== 9. 顧客データの初期ロード =====
  (async () => {
    const customers = await window.aivicApi.list(1);
    if (customers) {
      allCustomers = customers;
    }
  })();
}

function(container, apiUrl, tables) {
  const contractTable = tables[0];
  const contractHistoryTable = tables[2];
  const billingTable = tables[3];

  let allContracts = contractTable.records || [];
  let selectedContractId = null;
  let editingContractId = null;

  // 1. テーブル再描画関数
  function renderContractRows(rows) {
    const tbody = container.querySelector("#contract-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">契約がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const statusColor = r.契約ステータス === '契約済' ? '#4ade80' : 
                          r.契約ステータス === '完了' ? '#60a5fa' :
                          r.契約ステータス === '終了' ? '#ef4444' :
                          r.契約ステータス === '承認待ち' ? '#f59e0b' : '#9ca3af';
      return `
        <tr data-id="${r.契約ID}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 8px; color: var(--text);">${r.契約名 || ''}</td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 11px;">${r.顧客企業ID ? r.顧客企業ID.substring(0, 8) : '-'}</td>
          <td style="padding: 8px; text-align: center;">
            <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; background: ${statusColor}; color: #fff; font-size: 11px; font-weight: 600;">${r.契約ステータス || '-'}</span>
          </td>
          <td style="padding: 8px; text-align: right; color: var(--text);">¥${(r.契約金額 || 0).toLocaleString()}</td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ描画
  renderContractRows(allContracts);

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const nameFilter = container.querySelector("#search-contract-name").value.toLowerCase();
    const statusFilter = container.querySelector("#filter-status").value;

    let filtered = allContracts.filter(r => {
      const nameMatch = !nameFilter || (r.契約名 || '').toLowerCase().includes(nameFilter);
      const statusMatch = !statusFilter || r.契約ステータス === statusFilter;
      return nameMatch && statusMatch;
    });

    renderContractRows(filtered);
  });

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#search-contract-name").value = '';
    container.querySelector("#filter-status").value = '';
    renderContractRows(allContracts);
  });

  // 4. 行クリックで詳細表示
  container.addEventListener("click", async e => {
    const row = e.target.closest("tr[data-id]");
    if (!row) return;

    selectedContractId = row.dataset.id;
    const contract = allContracts.find(c => c.契約ID === selectedContractId);

    if (contract) {
      // 詳細パネル更新
      const detailContent = container.querySelector("#detail-content");
      detailContent.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 12px;">
          <div>
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">契約ID</div>
            <div style="font-size: 12px; color: var(--text); word-break: break-all;">${contract.契約ID || '-'}</div>
          </div>
          <div>
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">ステータス</div>
            <div style="font-size: 12px; color: var(--text);">${contract.契約ステータス || '-'}</div>
          </div>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 12px;">
          <div>
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">開始日</div>
            <div style="font-size: 12px; color: var(--text);">${contract.契約開始日 ? new Date(contract.契約開始日).toLocaleDateString('ja-JP') : '-'}</div>
          </div>
          <div>
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">終了日</div>
            <div style="font-size: 12px; color: var(--text);">${contract.契約終了日 ? new Date(contract.契約終了日).toLocaleDateString('ja-JP') : '-'}</div>
          </div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">契約金額</div>
          <div style="font-size: 14px; color: #fbbf24; font-weight: 600;">¥${(contract.契約金額 || 0).toLocaleString()}</div>
        </div>
        <div style="margin-bottom: 12px;">
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">契約内容</div>
          <div style="font-size: 12px; color: var(--text); line-height: 1.5; max-height: 100px; overflow-y: auto;">${contract.契約内容 || '-'}</div>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px;">
          <button class="action-btn secondary edit-contract-btn" data-id="${contract.契約ID}" style="padding: 6px 10px; font-size: 12px;">編集</button>
          <button class="action-btn secondary view-history-btn" data-id="${contract.契約ID}" style="padding: 6px 10px; font-size: 12px;">履歴</button>
        </div>
      `;

      // 請求整合性チェック
      const billingCheckContent = container.querySelector("#billing-check-content");
      const relatedBillings = billingTable.records.filter(b => b.契約ID === selectedContractId) || [];

      if (relatedBillings.length === 0) {
        billingCheckContent.innerHTML = '<p style="color: var(--text-muted); text-align: center; padding: 10px 0;">関連する請求がありません</p>';
      } else {
        let checkHtml = '';
        relatedBillings.forEach(b => {
          const match = Math.abs((b.請求金額 || 0) - (contract.契約金額 || 0)) < 1;
          const checkStatus = match ? '✓ 一致' : '⚠ 不一致';
          const checkColor = match ? '#4ade80' : '#ef4444';
          checkHtml += `
            <div style="padding: 8px; margin-bottom: 8px; background: rgba(255,255,255,0.05); border-left: 3px solid ${checkColor}; border-radius: 3px;">
              <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
                <span style="font-size: 11px; color: var(--text-muted);">${b.請求年月 || '-'}</span>
                <span style="font-size: 11px; font-weight: 600; color: ${checkColor};">${checkStatus}</span>
              </div>
              <div style="font-size: 12px; color: var(--text);">請求: ¥${(b.請求金額 || 0).toLocaleString()}</div>
              <div style="font-size: 11px; color: var(--text-muted);">状態: ${b.請求ステータス || '-'}</div>
            </div>
          `;
        });
        billingCheckContent.innerHTML = checkHtml;
      }
    }
  });

  // 5. 編集ボタン
  container.addEventListener("click", e => {
    const editBtn = e.target.closest(".edit-contract-btn");
    if (!editBtn) return;

    editingContractId = editBtn.dataset.id;
    const contract = allContracts.find(c => c.契約ID === editingContractId);

    if (contract) {
      container.querySelector("#edit-contract-name").value = contract.契約名 || '';
      container.querySelector("#edit-status").value = contract.契約ステータス || '';
      container.querySelector("#edit-start-date").value = contract.契約開始日 ? contract.契約開始日.split('T')[0] : '';
      container.querySelector("#edit-end-date").value = contract.契約終了日 ? contract.契約終了日.split('T')[0] : '';
      container.querySelector("#edit-amount").value = contract.契約金額 || '';
      container.querySelector("#edit-content").value = contract.契約内容 || '';

      container.querySelector("#edit-modal").style.display = 'block';
    }
  });

  // 編集キャンセル
  container.querySelector("#btn-cancel-edit").addEventListener("click", () => {
    container.querySelector("#edit-modal").style.display = 'none';
  });

  // 編集保存
  container.querySelector("#btn-save-edit").addEventListener("click", async () => {
    const updated = {
      契約名: container.querySelector("#edit-contract-name").value,
      契約ステータス: container.querySelector("#edit-status").value,
      契約開始日: container.querySelector("#edit-start-date").value,
      契約終了日: container.querySelector("#edit-end-date").value,
      契約金額: parseInt(container.querySelector("#edit-amount").value) || 0,
      契約内容: container.querySelector("#edit-content").value
    };

    const result = await window.aivicApi.update(0, editingContractId, updated);
    if (result) {
      container.querySelector("#edit-modal").style.display = 'none';
      const updated_list = await window.aivicApi.list(0);
      allContracts = updated_list || [];
      renderContractRows(allContracts);
      selectedContractId = editingContractId;
      const row = container.querySelector(`tr[data-id="${editingContractId}"]`);
      if (row) row.click();
    }
  });

  // 6. 履歴表示
  container.addEventListener("click", async e => {
    const historyBtn = e.target.closest(".view-history-btn");
    if (!historyBtn) return;

    const contractId = historyBtn.dataset.id;
    const histories = contractHistoryTable.records.filter(h => h.契約ID === contractId) || [];

    const timelineHtml = histories.length === 0 
      ? '<p style="color: var(--text-muted); text-align: center; padding: 20px 0;">変更履歴がありません</p>'
      : histories.map(h => `
        <div style="padding: 12px; margin-bottom: 10px; background: rgba(255,255,255,0.05); border-left: 3px solid #f59e0b; border-radius: 3px;">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
            <span style="font-size: 12px; font-weight: 600; color: var(--text);">${h.変更種別 || '-'}</span>
            <span style="font-size: 10px; color: var(--text-muted);">${h.作成日時 ? new Date(h.作成日時).toLocaleString('ja-JP') : '-'}</span>
          </div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">フィールド: ${h.変更フィールド名 || '-'}</div>
          <div style="font-size: 11px; color: var(--text); margin-bottom: 2px;">変更前: <span style="color: #ef4444;">${h.変更前値 || '-'}</span></div>
          <div style="font-size: 11px; color: var(--text);">変更後: <span style="color: #4ade80;">${h.変更後値 || '-'}</span></div>
          <div style="font-size: 10px; color: var(--text-muted); margin-top: 4px;">作成者: ${h.作成者ID || '-'}</div>
        </div>
      `).join("");

    container.querySelector("#history-timeline").innerHTML = timelineHtml;
    container.querySelector("#history-modal").style.display = 'block';
  });

  // 履歴モーダル閉じる
  container.querySelector("#btn-close-history").addEventListener("click", () => {
    container.querySelector("#history-modal").style.display = 'none';
  });

  // モーダル外クリックで閉じる
  container.querySelector("#edit-modal").addEventListener("click", e => {
    if (e.target === container.querySelector("#edit-modal")) {
      container.querySelector("#edit-modal").style.display = 'none';
    }
  });

  container.querySelector("#history-modal").addEventListener("click", e => {
    if (e.target === container.querySelector("#history-modal")) {
      container.querySelector("#history-modal").style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#list-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const noSelection = container.querySelector("#no-selection");
  const inputContractId = container.querySelector("#input-contract-id");
  const inputCustomerName = container.querySelector("#input-customer-name");
  const inputBillingStart = container.querySelector("#input-billing-start");
  const inputBillingEnd = container.querySelector("#input-billing-end");
  const selectStatus = container.querySelector("#select-verification-status");
  const btnSearch = container.querySelector("#btn-search");
  const btnReset = container.querySelector("#btn-reset");

  let allRows = [];
  let selectedRowId = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    allRows = rows;
    if (rows.length === 0) {
      tbody.innerHTML = `<tr style="background: rgba(0,0,0,0.15); height: 40px;"><td colspan="6" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">該当データがありません</td></tr>`;
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const contractAmount = r.contract_amount || 0;
      const billingAmount = r.billing_amount || 0;
      const diff = billingAmount - contractAmount;
      const hasDiff = Math.abs(diff) > 0;
      const status = r.verification_status || "未検証";

      const rowBg = hasDiff ? "rgba(255, 107, 107, 0.08)" : "rgba(0,0,0,0.08)";
      const diffColor = hasDiff ? "#ff6b6b" : "var(--text)";

      return `<tr data-id="${r.id}" style="background: ${rowBg}; cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); transition: background 0.15s;" class="row-item">
        <td style="padding: 8px; color: var(--text); font-size: 11px; font-family: monospace;">${(r.contract_id || "").substring(0, 8)}</td>
        <td style="padding: 8px; color: var(--text); font-size: 12px;">${r.customer_name || "-"}</td>
        <td style="padding: 8px; text-align: right; color: var(--text); font-size: 12px;">${(contractAmount || 0).toLocaleString()}円</td>
        <td style="padding: 8px; text-align: right; color: var(--text); font-size: 12px;">${(billingAmount || 0).toLocaleString()}円</td>
        <td style="padding: 8px; text-align: center; color: ${diffColor}; font-size: 12px; font-weight: ${hasDiff ? "600" : "400"};">${hasDiff ? `${diff > 0 ? "+" : ""}${diff.toLocaleString()}円` : "−"}</td>
        <td style="padding: 8px; text-align: center; font-size: 11px;">
          <span style="display: inline-block; padding: 3px 6px; border-radius: 3px; background: ${status === "差異検出" ? "rgba(255, 107, 107, 0.2)" : status === "検証済み" ? "rgba(76, 175, 80, 0.2)" : "rgba(158, 158, 158, 0.2)"}; color: ${status === "差異検出" ? "#ff6b6b" : status === "検証済み" ? "#4caf50" : "var(--text-muted)"};">${status}</span>
        </td>
      </tr>`;
    }).join("");

    // 行クリックで詳細表示
    container.querySelectorAll(".row-item").forEach(row => {
      row.addEventListener("click", () => {
        selectedRowId = row.dataset.id;
        const record = rows.find(r => r.id === selectedRowId);
        if (record) showDetail(record);

        // ハイライト
        container.querySelectorAll(".row-item").forEach(r => r.style.opacity = "0.6");
        row.style.opacity = "1";
      });
    });
  }

  // 2. 詳細パネル表示関数
  function showDetail(record) {
    noSelection.style.display = "none";
    detailPanel.style.display = "block";

    const contractAmount = record.contract_amount || 0;
    const billingAmount = record.billing_amount || 0;
    const diff = billingAmount - contractAmount;
    const hasDiff = Math.abs(diff) > 0;

    const detailHtml = `
      <div class="card" style="padding: 12px; margin-bottom: 12px;">
        <h4 style="margin: 0 0 10px 0; font-size: 13px; font-weight: 600; color: var(--text);">契約情報</h4>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px;">
          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">契約ID</div>
            <div style="color: var(--text); font-family: monospace; font-weight: 500;">${record.contract_id || "-"}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">顧客名</div>
            <div style="color: var(--text); font-weight: 500;">${record.customer_name || "-"}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">契約開始日</div>
            <div style="color: var(--text);">${record.contract_start_date ? new Date(record.contract_start_date).toLocaleDateString("ja-JP") : "-"}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">契約終了日</div>
            <div style="color: var(--text);">${record.contract_end_date ? new Date(record.contract_end_date).toLocaleDateString("ja-JP") : "-"}</div>
