          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">請求年月</div>
            <div style="color: var(--text);">${record.billing_month || "-"}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">請求日</div>
            <div style="color: var(--text);">${record.billing_date ? new Date(record.billing_date).toLocaleDateString("ja-JP") : "-"}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">支払期限</div>
            <div style="color: var(--text);">${record.payment_due_date ? new Date(record.payment_due_date).toLocaleDateString("ja-JP") : "-"}</div>
          </div>
          <div style="grid-column: 1 / -1;">
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">請求金額</div>
            <div style="color: var(--text); font-size: 14px; font-weight: 600;">${(billingAmount || 0).toLocaleString()}円</div>
          </div>
        </div>
      </div>

      <div class="card" style="padding: 12px; margin-bottom: 12px; border-left: 3px solid ${hasDiff ? "#ff6b6b" : "#4caf50"};">
        <h4 style="margin: 0 0 10px 0; font-size: 13px; font-weight: 600; color: var(--text);">照合結果</h4>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px; margin-bottom: 10px;">
          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">差異金額</div>
            <div style="color: ${hasDiff ? "#ff6b6b" : "#4caf50"}; font-size: 14px; font-weight: 600;">${hasDiff ? `${diff > 0 ? "+" : ""}${diff.toLocaleString()}円` : "差異なし"}</div>
          </div>
          <div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">検証ステータス</div>
            <div style="color: var(--text); font-weight: 500;">${record.verification_status || "未検証"}</div>
          </div>
        </div>
        ${record.difference_reason ? `<div style="padding: 8px; background: rgba(0,0,0,0.2); border-radius: 3px; font-size: 11px; color: var(--text-muted); margin-bottom: 8px;"><strong>差異理由:</strong> ${record.difference_reason}</div>` : ""}
      </div>

      <div style="display: flex; gap: 6px;">
        <button class="action-btn detail-approve-btn" data-id="${record.id}" style="flex: 1; padding: 8px 12px; font-size: 12px; font-weight: 600;">承認</button>
        <button class="action-btn secondary detail-edit-btn" data-id="${record.id}" style="flex: 1; padding: 8px 12px; font-size: 12px; font-weight: 600;">編集</button>
        <button class="action-btn secondary detail-reject-btn" data-id="${record.id}" style="flex: 1; padding: 8px 12px; font-size: 12px; font-weight: 600;">却下</button>
      </div>
    `;

    detailPanel.innerHTML = detailHtml;

    // 詳細パネルのボタンイベント
    detailPanel.querySelector(".detail-approve-btn").addEventListener("click", async () => {
      await window.aivicApi.update(0, record.id, { verification_status: "検証済み" });
      window.aivicApi.list(0).then(renderRows);
      noSelection.style.display = "flex";
      detailPanel.style.display = "none";
    });

    detailPanel.querySelector(".detail-reject-btn").addEventListener("click", async () => {
      await window.aivicApi.update(0, record.id, { verification_status: "差異検出" });
      window.aivicApi.list(0).then(renderRows);
      noSelection.style.display = "flex";
      detailPanel.style.display = "none";
    });

    detailPanel.querySelector(".detail-edit-btn").addEventListener("click", () => {
      window.showScreen("scr-1781957515797"); // 差異検出・調整画面へ遷移
    });
  }

  // 3. 初期データ表示
  renderRows(tables[0]?.records || []);

  // 4. 検索ボタン
  btnSearch.addEventListener("click", async () => {
    const contractId = inputContractId.value.trim();
    const customerName = inputCustomerName.value.trim();
    const billingStart = inputBillingStart.value;
    const billingEnd = inputBillingEnd.value;
    const status = selectStatus.value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (contractId && !(r.contract_id || "").includes(contractId)) return false;
      if (customerName && !(r.customer_name || "").includes(customerName)) return false;
      if (billingStart && (r.billing_month || "") < billingStart) return false;
      if (billingEnd && (r.billing_month || "") > billingEnd) return false;
      if (status && r.verification_status !== status) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 5. リセットボタン
  btnReset.addEventListener("click", () => {
    inputContractId.value = "";
    inputCustomerName.value = "";
    inputBillingStart.value = "";
    inputBillingEnd.value = "";
    selectStatus.value = "";
    renderRows(tables[0]?.records || []);
    noSelection.style.display = "flex";
    detailPanel.style.display = "none";
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=契約履歴, 1=ユーザー
  const contractHistoryIdx = 0;
  const userIdx = 1;

  let selectedApplicationId = null;
  let currentValidationResults = [];
  let currentErrors = [];

  // ========== 1. 申請一覧の再描画 ==========
  function renderApplicationsList(applications) {
    const list = container.querySelector("#applications-list");
    if (!applications || applications.length === 0) {
      list.innerHTML = '<div style="padding: 8px; font-size: 12px; color: var(--text-muted);">申請がありません</div>';
      return;
    }

    list.innerHTML = applications.map(app => {
      const statusColor = {
        '未検証': 'rgba(255,150,0,0.2)',
        '検証済': 'rgba(100,200,100,0.2)',
        '差異検出': 'rgba(255,100,100,0.2)',
        '承認待ち': 'rgba(100,150,255,0.2)'
      }[app.請求検証ステータス] || 'rgba(255,255,255,0.1)';

      return `
        <div class="application-card" data-id="${app.契約履歴ID}" style="padding: 10px; background: ${statusColor}; border-radius: 3px; border-left: 2px solid var(--primary); cursor: pointer; transition: all 0.2s;">
          <div style="font-size: 11px; font-weight: 600; color: var(--text); margin-bottom: 4px;">ID: ${app.契約履歴ID.substring(0, 8)}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">変更: ${app.変更種別 || '-'}</div>
          <div style="font-size: 10px; color: var(--text-muted);">作成: ${new Date(app.作成日時).toLocaleDateString('ja-JP')}</div>
          <div style="font-size: 10px; padding: 3px 6px; background: rgba(255,255,255,0.1); border-radius: 2px; margin-top: 4px; color: var(--text-muted);">${app.請求検証ステータス || '未検証'}</div>
        </div>
      `;
    }).join('');

    // イベントデリゲーション: 申請カード選択
    container.querySelectorAll('.application-card').forEach(card => {
      card.addEventListener('click', () => {
        container.querySelectorAll('.application-card').forEach(c => c.style.opacity = '0.6');
        card.style.opacity = '1';
        selectedApplicationId = card.dataset.id;
        displayApplicationDetail(applications.find(a => a.契約履歴ID === selectedApplicationId));
      });
    });
  }

  // ========== 2. 申請詳細表示 ==========
  function displayApplicationDetail(app) {
    if (!app) return;

    container.querySelector("#detail-title").textContent = `申請 ${app.契約履歴ID.substring(0, 8)}`;
    container.querySelector("#detail-status").textContent = app.請求検証ステータス || '未検証';
    container.querySelector("#detail-applicant").textContent = app.作成者 || '-';
    container.querySelector("#detail-date").textContent = new Date(app.作成日時).toLocaleDateString('ja-JP');

    // 変更前後の比較
    let beforeHtml = '<div style="color: var(--text-muted);">-</div>';
    let afterHtml = '<div style="color: var(--text-muted);">-</div>';

    if (app.変更前値) {
      try {
        const before = typeof app.変更前値 === 'string' ? JSON.parse(app.変更前値) : app.変更前値;
        beforeHtml = Object.entries(before).map(([k, v]) => 
          `<div><strong>${k}:</strong> ${v}</div>`
        ).join('');
      } catch (e) {
        beforeHtml = `<div>${app.変更前値}</div>`;
      }
    }

    if (app.変更後値) {
      try {
        const after = typeof app.変更後値 === 'string' ? JSON.parse(app.変更後値) : app.変更後値;
        afterHtml = Object.entries(after).map(([k, v]) => 
          `<div><strong>${k}:</strong> ${v}</div>`
        ).join('');
      } catch (e) {
        afterHtml = `<div>${app.変更後値}</div>`;
      }
    }

    container.querySelector("#before-content").innerHTML = beforeHtml;
    container.querySelector("#after-content").innerHTML = afterHtml;

    // 検証結果・エラーをクリア
    currentValidationResults = [];
    currentErrors = [];
    container.querySelector("#validation-results").innerHTML = '<div style="color: var(--text-muted);">検証を実行してください</div>';
    container.querySelector("#error-list").innerHTML = '<div style="color: var(--text-muted);">-</div>';
  }

  // ========== 3. 検証実行 ==========
  container.querySelector("#btn-validate").addEventListener("click", async () => {
    if (!selectedApplicationId) {
      alert("申請を選択してください");
      return;
    }

    // 検証ルール選択モーダルを表示
    container.querySelector("#modal-rule-select").style.display = "flex";
  });

  container.querySelector("#btn-rule-apply").addEventListener("click", async () => {
    const rule = container.querySelector("#rule-select").value;
    if (!rule) {
      alert("ルールを選択してください");
      return;
    }

    container.querySelector("#modal-rule-select").style.display = "none";

    // 検証実行（シミュレーション）
    currentValidationResults = [
      { type: 'info', message: '基本的な形式チェック: OK' },
      { type: 'info', message: '契約金額の範囲チェック: OK' },
      { type: 'warning', message: '変更日が契約終了日を超えています' },
      { type: 'success', message: '請求データとの整合性: 確認済み' }
    ];

    currentErrors = [
      { severity: 'warning', message: '契約終了日が変更後の開始日より前です' },
      { severity: 'info', message: '顧客企業の支払条件が変更されています' }
    ];

    // 検証結果を表示
    const resultsHtml = currentValidationResults.map(r => {
      const icon = r.type === 'success' ? '✓' : r.type === 'warning' ? '⚠' : 'ℹ';
      const color = r.type === 'success' ? '#64c864' : r.type === 'warning' ? '#ff9600' : '#6496ff';
      return `<div style="padding: 6px; border-left: 2px solid ${color}; color: var(--text); font-size: 11px;">${icon} ${r.message}</div>`;
    }).join('');
    container.querySelector("#validation-results").innerHTML = resultsHtml;

    // エラー・警告を表示
    const errorsHtml = currentErrors.map(e => {
      const icon = e.severity === 'warning' ? '⚠' : 'ℹ';
      return `<div style="padding: 6px; border-left: 2px solid ${e.severity === 'warning' ? '#ff9600' : '#6496ff'}; color: var(--text); font-size: 11px;">${icon} ${e.message}</div>`;
    }).join('');
    container.querySelector("#error-list").innerHTML = errorsHtml || '<div style="color: var(--text-muted);">エラーなし</div>';
  });

  container.querySelector("#btn-rule-cancel").addEventListener("click", () => {
    container.querySelector("#modal-rule-select").style.display = "none";
  });

  // ========== 4. 自動確認 ==========
  container.querySelector("#btn-auto-approve").addEventListener("click", async () => {
    if (!selectedApplicationId) {
      alert("申請を選択してください");
      return;
    }

    if (!confirm("この申請を自動確認しますか？")) return;

    // API呼び出し（シミュレーション）
    const updated = await window.aivicApi.update(contractHistoryIdx, selectedApplicationId, {
      請求検証ステータス: '検証済'
    });

    if (updated) {
      alert("自動確認が完了しました");
      // 一覧を再読み込み
      const apps = await window.aivicApi.list(contractHistoryIdx);
      renderApplicationsList(apps);
    }
  });

  // ========== 5. 手動確認 ==========
  container.querySelector("#btn-manual-approve").addEventListener("click", () => {
    if (!selectedApplicationId) {
      alert("申請を選択してください");
      return;
    }

    container.querySelector("#modal-approver").style.display = "flex";
  });

  container.querySelector("#btn-approver-assign").addEventListener("click", async () => {
    const approver = container.querySelector("#approver-select").value;
    const priority = document.querySelector('input[name="priority"]:checked').value;
    const notes = container.querySelector("#approver-notes").value;

    if (!approver) {
      alert("承認者を選択してください");
      return;
    }

    container.querySelector("#modal-approver").style.display = "none";

    // API呼び出し
    const updated = await window.aivicApi.update(contractHistoryIdx, selectedApplicationId, {
      請求検証ステータス: '承認待ち',
      備考: notes
    });

    if (updated) {
      alert(`承認者 ${approver} に割り当てました（優先度: ${priority}）`);
      const apps = await window.aivicApi.list(contractHistoryIdx);
      renderApplicationsList(apps);
    }
  });

  container.querySelector("#btn-approver-cancel").addEventListener("click", () => {
    container.querySelector("#modal-approver").style.display = "none";
  });

  // ========== 6. 却下 ==========
  container.querySelector("#btn-reject").addEventListener("click", () => {
    if (!selectedApplicationId) {
      alert("申請を選択してください");
      return;
    }

    container.querySelector("#modal-reject").style.display = "flex";
  });

  container.querySelector("#btn-reject-confirm").addEventListener("click", async () => {
    const reason = container.querySelector("#reject-reason").value;

    if (!reason.trim()) {
      alert("却下理由を入力してください");
      return;
    }

    container.querySelector("#modal-reject").style.display = "none";

    // API呼び出し
    const updated = await window.aivicApi.update(contractHistoryIdx, selectedApplicationId, {
      請求検証ステータス: '差異検出',
      備考: `却下: ${reason}`
    });

    if (updated) {
      alert("申請を却下しました");
      const apps = await window.aivicApi.list(contractHistoryIdx);
      renderApplicationsList(apps);
      container.querySelector("#reject-reason").value = '';
    }
  });

  container.querySelector("#btn-reject-cancel").addEventListener("click", () => {
    container.querySelector("#modal-reject").style.display = "none";
  });

  // ========== 7. 検索 ==========
  container.querySelector("#search-application").addEventListener("input", async (e) => {
    const keyword = e.target.value.toLowerCase();
    const apps = await window.aivicApi.list(contractHistoryIdx);
    const filtered = apps.filter(a => 
      (a.契約履歴ID && a.契約履歴ID.toLowerCase().includes(keyword)) ||
      (a.変更種別 && a.変更種別.toLowerCase().includes(keyword)) ||
      (a.作成者 && a.作成者.toLowerCase().includes(keyword))
    );
    renderApplicationsList(filtered);
  });

  // ========== 8. 初期データ読み込み ==========
  (async () => {
    const apps = await window.aivicApi.list(contractHistoryIdx);
    renderApplicationsList(apps);
  })();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#agreement-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const agreementForm = container.querySelector("#agreement-form");
  const notificationForm = container.querySelector("#notification-form");
  const historyPanel = container.querySelector("#history-panel");
  const messagePreview = container.querySelector("#message-preview");
  const notificationMessage = container.querySelector("[data-testid='notification-message']");

  let selectedContractId = null;
  let currentContractData = null;

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.合意状態 === "待機中" ? "#ff6a00" : r.合意状態 === "確認済" ? "#4ade80" : "#ef4444";
      const deadline = r.合意期限 ? new Date(r.合意期限).toLocaleDateString("ja-JP") : "—";
      return `
        <tr data-id="${r.id || r.契約ID}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;">
          <td style="padding: 10px 12px; color: var(--text); font-weight: 600;">${r.契約ID || "—"}</td>
          <td style="padding: 10px 12px; color: var(--text);">${r.顧客名 || "—"}</td>
          <td style="padding: 10px 12px; color: var(--text-muted); font-size: 12px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${r.変更内容 || "—"}</td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text); font-size: 12px;">${deadline}</td>
          <td style="padding: 10px 12px; text-align: center;">
            <span style="display: inline-block; padding: 4px 8px; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 11px; font-weight: 600;">${r.合意状態 || "—"}</span>
          </td>
        </tr>
      `;
    }).join("");

    // 行クリックで詳細表示
    container.querySelectorAll("#agreement-tbody tr").forEach(row => {
      row.addEventListener("click", () => {
        selectedContractId = row.dataset.id;
        const rowData = rows.find(r => (r.id || r.契約ID) === selectedContractId);
        if (rowData) {
          currentContractData = rowData;
          showDetail(rowData);
        }
      });
    });
  }

  // 2. 詳細パネル表示
  function showDetail(data) {
    container.querySelector("#detail-contract-id").textContent = data.契約ID || "—";
    container.querySelector("#detail-customer-name").textContent = data.顧客名 || "—";
    container.querySelector("#detail-change-content").textContent = data.変更内容 || "—";
    const deadline = data.合意期限 ? new Date(data.合意期限).toLocaleDateString("ja-JP") : "—";
    container.querySelector("#detail-deadline").textContent = deadline;

    // 確認者・確認日時を自動入力（現在のユーザー・現在時刻）
    const now = new Date();
    container.querySelector("[data-testid='confirmer-name']").value = "現在のユーザー"; // 実装時は window.currentUser から取得
    container.querySelector("[data-testid='confirmation-datetime']").value = now.toLocaleString("ja-JP");

    detailPanel.style.display = "block";
    agreementForm.style.display = "block";
    notificationForm.style.display = "block";
    historyPanel.style.display = "block";

    // 処理履歴を表示
    renderHistory(data);
  }

  // 3. 処理履歴表示
  function renderHistory(data) {
    const historyList = container.querySelector("#history-list");
    const history = [
      { date: "2025-01-15 10:30", user: "営業 太郎", action: "合意確認", status: "✓ 確認済" },
      { date: "2025-01-14 14:20", user: "営業 花子", action: "合意待ち", status: "⏳ 待機中" },
    ];
    historyList.innerHTML = history.map(h => `
      <div style="padding: 6px; background: rgba(255,255,255,0.04); border-radius: 3px;">
        <div style="color: var(--text-muted); margin-bottom: 2px;">${h.date}</div>
        <div style="color: var(--text); font-weight: 600;">${h.action}</div>
        <div style="color: var(--text-muted); font-size: 10px;">${h.user}</div>
      </div>
    `).join("");
  }

  // 4. 初期データ描画
  const initialRows = tables[0]?.records || [];
  renderRows(initialRows);

  // 5. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", async () => {
    const status = container.querySelector("[data-testid='agreement-status-filter']").value;
    const keyword = container.querySelector("[data-testid='search-keyword']").value.toLowerCase();

    const rows = await window.aivicApi.list(0) || initialRows;
    const filtered = rows.filter(r => {
      const matchStatus = !status || r.合意状態 === status;
      const matchKeyword = !keyword || 
        (r.契約ID || "").toLowerCase().includes(keyword) ||
        (r.顧客名 || "").toLowerCase().includes(keyword);
      return matchStatus && matchKeyword;
    });
    renderRows(filtered);
  });

  // 6. 合意確認ボタン
  container.querySelector("[data-testid='confirm-agreement-btn']").addEventListener("click", async () => {
    if (!selectedContractId) {
      alert("契約を選択してください");
      return;
    }
    if (confirm("この契約の合意を確認しますか？")) {
      const now = new Date().toISOString();
      await window.aivicApi.update(0, selectedContractId, {
        合意状態: "確認済",
        合意確認日時: now,
        確認者名: "現在のユーザー"
      });
      const rows = await window.aivicApi.list(0) || initialRows;
      renderRows(rows);
      alert("合意を確認しました");
    }
  });

  // 7. 合意却下ボタン
  container.querySelector("[data-testid='reject-agreement-btn']").addEventListener("click", async () => {
    if (!selectedContractId) {
      alert("契約を選択してください");
      return;
    }
    if (confirm("この契約の合意を却下しますか？")) {
      const now = new Date().toISOString();
      await window.aivicApi.update(0, selectedContractId, {
        合意状態: "却下",
        合意確認日時: now,
        確認者名: "現在のユーザー"
      });
      const rows = await window.aivicApi.list(0) || initialRows;
      renderRows(rows);
      alert("合意を却下しました");
    }
  });

  // 8. メッセージプレビュー
  notificationMessage.addEventListener("input", () => {
    messagePreview.textContent = notificationMessage.value || "（メッセージを入力してください）";
  });

  // 9. 通知送信ボタン
  container.querySelector("[data-testid='send-notification-btn']").addEventListener("click", async () => {
    const selectedUsers = Array.from(container.querySelector("[data-testid='notification-user-select']").selectedOptions).map(o => o.value);
    const message = notificationMessage.value;

    if (selectedUsers.length === 0) {
      alert("通知対象ユーザーを選択してください");
      return;
    }
    if (!message) {
      alert("通知メッセージを入力してください");
      return;
    }

    if (confirm(`${selectedUsers.length}人のユーザーに通知を送信しますか？`)) {
      // 通知送信処理（実装時は API 呼び出し）
      alert("通知を送信しました");
      notificationMessage.value = "";
      messagePreview.textContent = "";
      container.querySelector("[data-testid='notification-user-select']").selectedIndex = -1;
    }
  });

  // 10. フィルター変更時に自動検索
  container.querySelector("[data-testid='agreement-status-filter']").addEventListener("change", () => {
    container.querySelector("[data-testid='search-button']").click();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 請求(0), 請求明細(1), 契約(2), 顧客(3), 契約履歴(4)
  const invoiceTableIndex = 0;
  const detailTableIndex = 1;
  const contractTableIndex = 2;
  const customerTableIndex = 3;
  const historyTableIndex = 4;

  // ===== 1. 初期データ取得 & 表示 =====
  async function loadInvoiceData() {
    // URL パラメータから請求ID を取得（例: ?invoiceId=xxx）
    const params = new URLSearchParams(window.location.search);
    const invoiceId = params.get('invoiceId');

    if (!invoiceId) {
      container.querySelector('#invoice-id').textContent = 'パラメータエラー: invoiceId が指定されていません';
      return;
    }

    // 請求情報を取得
    const invoices = await window.aivicApi.list(invoiceTableIndex);
    const invoice = invoices?.find(inv => inv.id === invoiceId);

    if (!invoice) {
      container.querySelector('#invoice-id').textContent = `請求ID ${invoiceId} が見つかりません`;
      return;
    }

    // 顧客情報を取得
    const customers = await window.aivicApi.list(customerTableIndex);
    const customer = customers?.find(c => c.id === invoice.customer_id || c.顧客ID === invoice.customer_id);

    // 契約情報を取得
    const contracts = await window.aivicApi.list(contractTableIndex);
    const contract = contracts?.find(ct => ct.id === invoice.contract_id || ct.契約ID === invoice.contract_id);

    // 請求明細を取得
    const details = await window.aivicApi.list(detailTableIndex);
    const invoiceDetails = details?.filter(d => d.invoice_id === invoiceId || d.請求ID === invoiceId) || [];

    // 契約履歴を取得
    const histories = await window.aivicApi.list(historyTableIndex);
    const contractHistories = histories?.filter(h => h.contract_id === invoice.contract_id || h.契約ID === invoice.contract_id) || [];

    // ===== 請求ヘッダー情報を表示 =====
    container.querySelector('#invoice-id').textContent = invoice.id || invoice.請求ID || '-';
    container.querySelector('#customer-name').textContent = customer?.customer_name || customer?.顧客名 || '-';
    container.querySelector('#invoice-date').textContent = invoice.invoice_date ? new Date(invoice.invoice_date).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#invoice-status').textContent = invoice.invoice_status || invoice.請求ステータス || '-';

    // ===== 契約情報を表示 =====
    container.querySelector('#contract-id').textContent = contract?.id || contract?.契約ID || '-';
    container.querySelector('#contract-name').textContent = contract?.contract_name || contract?.契約名 || '-';
    container.querySelector('#contract-start-date').textContent = contract?.contract_start_date ? new Date(contract.contract_start_date).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#contract-end-date').textContent = contract?.contract_end_date ? new Date(contract.contract_end_date).toLocaleDateString('ja-JP') : '-';
    container.querySelector('#contract-amount').textContent = contract?.contract_amount ? `¥${(contract.contract_amount).toLocaleString()}` : '-';
    container.querySelector('#contract-status').textContent = contract?.contract_status || contract?.契約ステータス || '-';

    // ===== 請求金額を表示 =====
    container.querySelector('#invoice-amount').textContent = invoice.invoice_amount ? `¥${(invoice.invoice_amount).toLocaleString()}` : '¥0';
    container.querySelector('#payment-due-date').textContent = invoice.payment_due_date ? new Date(invoice.payment_due_date).toLocaleDateString('ja-JP') : '-';

    // ===== 請求明細テーブルを描画 =====
    renderInvoiceDetails(invoiceDetails);

    // ===== 変更履歴を表示 =====
    renderChangeHistory(contractHistories);

    // ===== 隠しフォームに ID を保存 =====
    container.querySelector('#current-invoice-id').value = invoiceId;
    container.querySelector('#current-contract-id').value = invoice.contract_id || invoice.契約ID || '';
  }

  // ===== 2. 請求明細テーブル描画 =====
  function renderInvoiceDetails(details) {
    const tbody = container.querySelector('#invoice-details-tbody');
    if (!details || details.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(212,175,55,0.1);"><td colspan="6" style="padding: 16px; text-align: center; color: var(--text-muted);">明細がありません</td></tr>';
      return;
    }

    tbody.innerHTML = details.map((d, idx) => {
      const amount = (d.amount || d.金額 || 0);
      const quantity = (d.quantity || d.数量 || 0);
      const unitPrice = (d.unit_price || d.単価 || 0);
      const verificationStatus = d.verification_status || d.検証ステータス || '未検証';

      let statusColor = '#9fb0d1';
      if (verificationStatus === '検証済み' || verificationStatus === 'verified') statusColor = '#27AE60';
      if (verificationStatus === '差異検出' || verificationStatus === 'mismatch') statusColor = '#E74C3C';

      return `
        <tr style="border-bottom: 1px solid rgba(212,175,55,0.1); ${idx % 2 === 0 ? 'background: rgba(212,175,55,0.04);' : ''}">
          <td style="padding: 6px 8px; color: var(--text);">${d.detail_type || d.明細種別 || '-'}</td>
          <td style="padding: 6px 8px; color: var(--text); font-size: 11px;">${d.description || d.説明 || '-'}</td>
          <td style="padding: 6px 8px; text-align: right; color: var(--text);">${quantity}</td>
          <td style="padding: 6px 8px; text-align: right; color: var(--text);">¥${unitPrice.toLocaleString()}</td>
          <td style="padding: 6px 8px; text-align: right; color: #D4AF37; font-weight: 600;">¥${amount.toLocaleString()}</td>
          <td style="padding: 6px 8px; text-align: center;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-size: 10px; font-weight: 600;">
              ${verificationStatus}
            </span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ===== 3. 変更履歴タイムライン描画 =====
  function renderChangeHistory(histories) {
    const container_hist = container.querySelector('#change-history');
    if (!histories || histories.length === 0) {
      container_hist.innerHTML = '<div style="color: var(--text-muted);">履歴がありません</div>';
      return;
    }

    container_hist.innerHTML = histories.slice(0, 5).map(h => {
      const changeType = h.change_type || h.変更種別 || '変更';
      const createdAt = h.created_at || h.作成日時 || '';
      const createdBy = h.creator_name || h.作成者 || '不明';
      const dateStr = createdAt ? new Date(createdAt).toLocaleDateString('ja-JP') : '-';

      return `
        <div style="margin-bottom: 6px; padding-bottom: 6px; border-bottom: 1px solid rgba(212,175,55,0.1);">
          <div style="font-size: 10px; color: #D4AF37; font-weight: 600;">${changeType}</div>
          <div style="font-size: 10px; color: var(--text-muted);">${dateStr} by ${createdBy}</div>
        </div>
      `;
    }).join('');
  }

  // ===== 4. 承認ボタン =====
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    const invoiceId = container.querySelector('#current-invoice-id').value;
    if (!invoiceId) {
      alert('請求IDが取得できません');
      return;
    }

    if (!confirm('この請求を承認しますか？')) return;

    const result = await window.aivicApi.update(invoiceTableIndex, invoiceId, {
      invoice_status: '承認済',
      請求ステータス: '承認済'
    });

    if (result) {
      alert('請求を承認しました');
      loadInvoiceData(); // 再表示
    }
  });

  // ===== 5. 却下ボタン =====
  container.querySelector('#btn-reject').addEventListener('click', () => {
    const noteContainer = container.querySelector('#approval-note-container');
    if (noteContainer.style.display === 'none') {
      noteContainer.style.display = 'block';
      container.querySelector('#rejection-reason').focus();
    } else {
      submitRejection();
    }
  });

  async function submitRejection() {
    const invoiceId = container.querySelector('#current-invoice-id').value;
    const reason = container.querySelector('#rejection-reason').value.trim();

    if (!invoiceId) {
      alert('請求IDが取得できません');
      return;
    }

    if (!reason) {
      alert('却下理由を入力してください');
      return;
    }

    if (!confirm('この請求を却下しますか？')) return;

    const result = await window.aivicApi.update(invoiceTableIndex, invoiceId, {
      invoice_status: '却下',
      請求ステータス: '却下',
      remarks: reason,
      摘要: reason
    });

    if (result) {
      alert('請求を却下しました');
      loadInvoiceData(); // 再表示
      container.querySelector('#approval-note-container').style.display = 'none';
      container.querySelector('#rejection-reason').value = '';
    }
  }

  // ===== 6. 初期ロード =====
  loadInvoiceData();
}
